  'products/veterinary/injectables/abatek-injection' => array('name'=>'Abatek Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/abatek.png','active'=>'Abamectin 10 mg (per ml)','composition'=>'Each ml contains: Abamectin 10 mg.','drug_class'=>'Macrocyclic lactone (avermectin) endectocide / antiparasitic','uses'=>'A veterinary injectable antiparasitic belonging to the avermectin group, used to control internal and external parasites such as gastrointestinal roundworms, lungworms, mites and lice in livestock. It is administered by a veterinarian as part of a parasite-control programme. Observe the prescribed withdrawal periods.','route'=>'Injection (parenteral, subcutaneous)','prescription'=>'rx','packs'=>'10ml | 20ml | 50ml | 100ml','desc'=>'Control of mites and certain insect pests on a variety of ornamental and horticultural crops and on cotton.'),
  'products/veterinary/injectables/adenophose-injection' => array('name'=>'Adenophose Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/adenophose.png','active'=>'Selenium 0.50 mg, Vitamin E 70.0 mg, Vitamin B1 20.0 mg, Vitamin B12 0.10 mg, Adenosine-5-Phosphate 5.00 mg (per ml)','composition'=>'Each ml contains: Selenium 0.50 mg, Vitamin E 70.0 mg, Vitamin B1 (Thiamine) 20.0 mg, Vitamin B12 0.10 mg, Adenosine-5-Phosphate 5.00 mg.','drug_class'=>'Selenium, vitamin E and B-vitamin metabolic/muscle-tonic supplement','uses'=>'A veterinary injectable supplement combining selenium, vitamin E, B-group vitamins and adenosine phosphate to support muscle and nerve metabolism. It is used as supportive nutritional therapy in conditions associated with selenium/vitamin E deficiency such as muscular degeneration (nutritional muscular dystrophy) in calves and lambs and related muscular or reproductive disorders. Administer under veterinary supervision.','route'=>'Injection (parenteral)','prescription'=>'rx','packs'=>'10ml | 50ml | 100ml','desc'=>'For muscular dystrophy in calves & lambs, placental retention, deforming syndrome in bavine and ovine. Reproduction in efficiay myocyles; myasthenia, neuritis and muscular fatigue.'),
  'products/veterinary/injectables/almox-15-la-injection' => array('name'=>'Almox 15% LA Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/almox-15.png','active'=>'Amoxicillin (as trihydrate) equivalent to 150 mg amoxicillin base (per ml)','composition'=>'Each ml contains: Amoxicillin trihydrate equivalent to 150 mg amoxicillin base (BP Vet Specification).','drug_class'=>'Aminopenicillin (beta-lactam) antibiotic, long-acting','uses'=>'A long-acting injectable broad-spectrum penicillin (aminopenicillin) antibiotic for veterinary use. It is indicated for bacterial infections caused by susceptible organisms, including those of the urogenital, respiratory, gastrointestinal and soft-tissue systems such as mastitis, metritis and similar conditions in livestock. Use under veterinary direction and observe the stated withdrawal periods.','route'=>'Injection (parenteral, intramuscular)','prescription'=>'rx','packs'=>'10ml | 30ml | 50ml | 100ml','desc'=>'Urogenital tract diseases: Mastitis, metritis, pyometra, retained placenta, navel ill, cystitis, nephritis & MMA-syndrome etc.'),
  'products/veterinary/injectables/almox-la-20-100ml' => array('name'=>'Almox LA 20% 100ml Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/almox-100.png','active'=>'Amoxicillin (as trihydrate) 200 mg (per ml)','composition'=>'Each ml contains: Amoxicillin as trihydrate (BP) 200 mg (BP Vet Specification).','drug_class'=>'Aminopenicillin (beta-lactam) antibiotic, long-acting','uses'=>'A long-acting injectable broad-spectrum penicillin (aminopenicillin) antibiotic for veterinary use, supplied in a 100 ml presentation. It is indicated for infections caused by susceptible bacteria, including urogenital, respiratory and soft-tissue conditions such as mastitis and metritis in livestock. Use under veterinary direction and observe the stated withdrawal periods.','route'=>'Injection (parenteral, intramuscular)','prescription'=>'rx','packs'=>'100ml','desc'=>'Urogenital tract diseases: Mastitis, metritis, pyometra, retained placenta, navel ill, cystitis, nephritis & MMA-syndrome etc.'),
  'products/veterinary/injectables/almox-la-20-50ml' => array('name'=>'Almox LA 20% 50ml Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/almox-50.png','active'=>'Amoxicillin (as trihydrate) 200 mg (per ml)','composition'=>'Each ml contains: Amoxicillin as trihydrate (BP) 200 mg (BP Vet Specification).','drug_class'=>'Aminopenicillin (beta-lactam) antibiotic, long-acting','uses'=>'A long-acting injectable broad-spectrum penicillin (aminopenicillin) antibiotic for veterinary use, supplied in a 50 ml presentation. It is indicated for infections caused by susceptible bacteria, including urogenital, respiratory and soft-tissue conditions such as mastitis and metritis in livestock. Use under veterinary direction and observe the stated withdrawal periods.','route'=>'Injection (parenteral, intramuscular)','prescription'=>'rx','packs'=>'50ml','desc'=>'Almox La 20% 50Ml by Star Laboratories.'),
  'products/veterinary/injectables/aminovital-injection' => array('name'=>'Aminovital Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/aminovital.png','active'=>'Essential amino acids (L-Arginine, L-Cysteine, L-Glutamine, Glycine, L-Histidine, L-Isoleucine, L-Leucine, L-Lysine, L-Methionine, L-Threonine, L-Tryptophan, L-Phenylalanine, L-Valine) with B-group vitamins (B1, Riboflavin, B6, Nicotinamide), Vitamin C, glucose and electrolytes (calcium, potassium, magnesium salts)','composition'=>'Each ml contains (active ingredients): L-Arginine HCl 1.44 mg, L-Cysteine HCl 3.20 mg, L-Glutamine 3.20 mg, Glycine 3.20 mg, L-Histidine 1.32 mg, L-Isoleucine 3.60 mg, L-Leucine HCl 4.28 mg, L-Lysine HCl 5.44 mg, L-Methionine 3.20 mg, L-Threonine 3.20 mg, L-Tryptophan 0.86 mg, L-Phenylalanine 5.00 mg, L-Valine 3.60 mg, Vitamin B1 4.00 mg, Riboflavin Sodium Phosphate 0.17 mg, Vitamin B6 0.34 mg, Nicotinamide 8.00 mg, Ascorbic Acid 4.00 mg, Glucose 33.00 mg, Calcium Chloride 0.08 mg, Potassium Chloride 0.21 mg, Magnesium Sulphate 0.08 mg (with mannitol, parabens, benzyl alcohol and water for injection as non-active ingredients).','drug_class'=>'Parenteral nutritional supplement (amino acids, vitamins, minerals and electrolytes)','uses'=>'A veterinary injectable nutritional supplement combining essential amino acids, B-group and C vitamins, glucose and trace minerals. It is used as supportive supplementation to help meet increased nutrient requirements associated with stress, intensive production, convalescence and reduced intake in livestock and poultry. Administer under veterinary supervision.','route'=>'Injection (parenteral)','prescription'=>'rx','packs'=>'50ml | 100ml','desc'=>'Aminovital Injection is a combination of essential vitamins, amino acids and oligo elements. The deficiency of Vitamins is observed in various types of stock farming and the productivity under intense conditions requires extraordinary allowances. At the time of overcrowding,chang in temperature, microbial infections, parasitism, the supplement of vitamins play vital role. Aminoacids,through biological process take part in growth and maintenance cycles i.e. in the defence and reproductive functions. Minerals are recognized as bio-catalysts. Their presence in minor quantities is important for chemical reactions owing to which the multiple organics complexes of the living organisms are elaborated, distributed and balanced.'),
  'products/veterinary/injectables/anatar-injection' => array('name'=>'Anatar Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/anatar.png','active'=>'Acepromazine Maleate 10 mg (per ml)','composition'=>'Each ml contains: Acepromazine Maleate 10 mg.','drug_class'=>'Phenothiazine sedative / tranquilizer (central nervous system depressant)','uses'=>'A veterinary injectable phenothiazine tranquilizer used for sedation and calming of animals. It is employed as a pre-anaesthetic agent and to provide chemical restraint, for example in dogs and cats, to facilitate handling and procedures. It must be administered by a veterinarian.','route'=>'Injection (parenteral)','prescription'=>'rx','packs'=>'50ml | 100ml','desc'=>'sedative/tranquilizer used as a pre-anesthetic and for chemical restraint in dogs and cats.'),
  'products/veterinary/injectables/atrostar-injection' => array('name'=>'Atrostar Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/atrostar.png','active'=>'Atropine Sulphate 1 mg (per ml)','composition'=>'Each ml contains: Atropine Sulphate (BP) 1 mg (BP Specification).','drug_class'=>'Antimuscarinic / anticholinergic agent','uses'=>'A veterinary injectable anticholinergic agent used during anaesthesia and surgery to reduce salivary and respiratory tract secretions. It is also used as supportive treatment in certain conditions such as organophosphate poisoning and to manage some cardiac and gastrointestinal effects, under veterinary direction. Administer by a veterinarian.','route'=>'Injection (parenteral)','prescription'=>'rx','packs'=>'25ml','desc'=>'To reduce saliva and fluid in the respiratory tract during surgery.'),
  'products/veterinary/injectables/biquin-injection' => array('name'=>'Biquin Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/biquin.png','active'=>'Quinapyramine Sulphate 1.5 g, Quinapyramine Chloride 1.0 g (per vial)','composition'=>'Each vial contains: Quinapyramine Sulphate 1.5 g, Quinapyramine Chloride 1.0 g.','drug_class'=>'Quinapyramine antiprotozoal (trypanocide)','uses'=>'A veterinary injectable trypanocidal medicine containing quinapyramine salts. It is used for the treatment and prevention of trypanosomiasis (surra) caused by Trypanosoma evansi, notably in camels. It should be administered by a veterinarian according to the prescribed regimen.','route'=>'Injection (parenteral); reconstituted from powder','prescription'=>'rx','packs'=>'20ml vial | 2.5gm powder for
