  'products/veterinary/injectables/diminazine-injection' => array('name'=>'Diminazine Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/diminazine.png','active'=>'Diminazene Diaceturate 35 mg','composition'=>'Each ml contains: Diminazene Diaceturate 35 mg.','drug_class'=>'Antiprotozoal (aromatic diamidine)','uses'=>'A veterinary injectable antiprotozoal containing diminazene diaceturate. It is intended for use against blood protozoan infections such as trypanosomiasis, babesiosis and theileriosis in animals. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml vial | 100ml','desc'=>'For the treatment and prophylaxis of Trypanosomiasis, Babesiosis, Theileriosis, Pyrexia of unknown origin and mixed haemoprotozoan infection.'),
  'products/veterinary/injectables/diminazine-plus-injection' => array('name'=>'Diminazine Plus Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/diminazine-plus.png','active'=>'Diminazene Aceturate 105 mg + Etilefrine 131 mg','composition'=>'Each ml contains: Diminazene Aceturate 105 mg and Etilefrine 131 mg.','drug_class'=>'Antiprotozoal (aromatic diamidine) combined with a sympathomimetic circulatory support agent','uses'=>'A veterinary injectable combining the antiprotozoal diminazene aceturate with the sympathomimetic etilefrine. It is intended for use against blood protozoan infections such as trypanosomiasis, babesiosis and theileriosis in animals, with circulatory support. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'10ml | 50ml | 100ml','desc'=>'For the treatment and prophylaxis of Trypanosomiasis, Babesiosis, Theileriosis, Pyrexia of unknown origin and mixed haemoprotozoan infection.'),
  'products/veterinary/injectables/dinax-injection' => array('name'=>'Dinax Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/dinax.png','active'=>'Danofloxacin (as Mesylate) 25 mg','composition'=>'Each ml contains: Danofloxacin (as Mesylate) 25 mg (as per innovator\'s specifications).','drug_class'=>'Fluoroquinolone antibacterial','uses'=>'A veterinary injectable antibiotic containing danofloxacin, a fluoroquinolone. It is intended for use in cattle against bovine respiratory disease associated with susceptible bacteria such as Mannheimia haemolytica and Pasteurella multocida. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml','desc'=>'For the treatment of bovine respiratory disease (BRD) associated with Mannheimia haemolytica and Pasteurella multocida in beef cattle and for the control of BRD in beef cattle at high risk of developing BRD associated with Mannheimia haemolytica and Pasteurella multocida.'),
  'products/veterinary/injectables/donum-injection' => array('name'=>'Donum Injection (Dormec Injection)','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/donum.png','active'=>'Doramectin 10 mg','composition'=>'Each ml contains: Doramectin 10 mg.','drug_class'=>'Macrocyclic lactone (avermectin) endectocide / antiparasitic','uses'=>'A veterinary injectable antiparasitic containing doramectin, a macrocyclic lactone. It is intended for use in cattle against internal and external parasites including gastrointestinal roundworms, lungworms, eyeworms, grubs, sucking lice and mange mites. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'10ml | 20ml | 50ml | 100ml','desc'=>'For the treatment of parasites such as gastrointestinal roundworms, lungworms, eyeworms, grubs, sucking lice and mange mites in cattle.'),
  'products/veterinary/injectables/durafer-injection' => array('name'=>'Durafex Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/durafex.png','active'=>'Furosemide 50 mg','composition'=>'Each ml contains: Furosemide 50 mg (USP specification).','drug_class'=>'Loop diuretic (saluretic)','uses'=>'A veterinary injectable diuretic containing furosemide. It is intended to support the management of fluid retention (edema), including conditions associated with cardiac insufficiency, in animals such as dogs and horses. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml','desc'=>'Injection is an effective diuretic-saluretic for use in the treatment of acute noninflammatory tissue edema in dogs and horses, and for use in the treatment of edema (pulmonary congestion, ascites) associated with cardiac insufficiency in the dog.'),
  'products/veterinary/injectables/eficol-injectable-suspension' => array('name'=>'Eficol Injection Suspension','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/eficol-injectable-suspension.png','active'=>'Flumequine 30 mg + Colistin Sulphate 200,000 IU','composition'=>'Each ml contains: Flumequine 30 mg and Colistin Sulphate 200,000 IU.','drug_class'=>'Fluoroquinolone antibacterial combined with a polymyxin (colistin) antibacterial','uses'=>'A veterinary injectable antibacterial combining flumequine with colistin sulphate. It is intended for use against digestive and respiratory infections caused by susceptible gram-negative organisms such as E. coli, Salmonella, Pasteurella and Haemophilus. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml | 100ml','desc'=>'For prevention and treatment of digestive and respiratory infections due to gram-negative micro-organisms particularly: E. coli, Salmonella, Pasteurella and Haemophillus.'),
  'products/veterinary/injectables/fencobal-injection' => array('name'=>'Fencobal Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/fencobal.png','active'=>'Butaphosphan 10 g + Cyanocobalamin (Vitamin B12) 5 mg per 100 ml','composition'=>'Each 100 ml contains: Butaphosphan 10 g and Vitamin B12 (Cyanocobalamin) 5 mg.','drug_class'=>'Metabolic stimulant / tonic (organic phosphorus compound with vitamin B12)','uses'=>'A veterinary injectable tonic combining butaphosphan, an organic phosphorus compound, with vitamin B12. It is intended to support phosphorus supplementation and to aid metabolic and general health functions in animals. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml | 100ml','desc'=>'To treat phosphorus deficiencies and to improve metabolism and immune function.'),
  'products/veterinary/injectables/flofenic-30-injection' => array('name'=>'Flofenic Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/flofenic.png','active'=>'Florfenicol 300 mg','composition'=>'Each ml contains: Florfenicol 300 mg (as per innovator specification).','drug_class'=>'Amphenicol (phenicol) antibacterial','uses'=>'A veterinary injectable antibiotic containing florfenicol, an amphenicol antibacterial. It is intended for use in cattle against bovine respiratory disease associated with susceptible bacteria and for bovine foot rot (interdigital phlegmon). Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml','desc'=>'For treatment of bovine respiratory disease (BRD) associated with Mannheimia haemolytica, Pasteurella multocida, and Histophilus somni, and for the treatment of bovine interdigital phlegmon (foot rot, acute interdigital necrobacillosis, infectious pododermatitis).'),
