  'products/veterinary/injectables/mericyl-injection' => array('name'=>'Mericyl Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/mericyl.png','active'=>'Disodium Arsono Acetate 5 g per 100 mL','composition'=>'Each 100 mL contains: Disodium Arsono Acetate 5 g.','drug_class'=>'Organic arsenical roborant / general metabolic tonic (veterinary)','uses'=>'A veterinary injectable used as a roborant and general tonic in animals. It is intended to support general body condition and vitality in debilitated or run-down animals as part of supportive care.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'10ml | 50ml | 100ml','desc'=>'It is used as a roborant and general tonic in veterinary practice.'),
  'products/veterinary/injectables/metafos-injection' => array('name'=>'Metafos Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/metafos.png','active'=>'Toldimfos Sodium 100 mg per mL','composition'=>'Each mL contains: Toldimfos Sodium 100 mg (innovator specification).','drug_class'=>'Organic phosphorus compound / metabolic stimulant and mineral (phosphorus) supplement (veterinary)','uses'=>'A veterinary injectable phosphorus-containing tonic used to address conditions associated with phosphorus deficiency in animals, such as infertility, delayed maturity and anoestrus. It is used to support reproductive and metabolic function as part of veterinary management.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml | 100ml','desc'=>'In the case of infertility, delayed maturity and anoestrus.'),
  'products/veterinary/injectables/mil-d-forte-injection' => array('name'=>'Mil-D-Forte Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/mil-d-forte.png','active'=>'Calcium Gluconate 20.83 g, Boric Acid 4.33 g, Magnesium Hypophosphite 5.33 g, Magnesium Chloride 2.00 g, Calcium D-Saccharate 1.00 g, Vitamin B1 100 mg, Vitamin B6 70 mg, Vitamin B12 3000 mcg, Nicotinamide 200 mg, Dextrose 20 g (per 100 mL)','composition'=>'Each 100 mL contains: Calcium Gluconate 20.83 g, Boric Acid 4.33 g, Magnesium Hypophosphite 5.33 g, Magnesium Chloride 2.00 g, Calcium D-Saccharate 1.00 g, Vitamin B1 100 mg, Vitamin B6 70 mg, Vitamin B12 3000 mcg, Nicotinamide 200 mg, Dextrose 20 g.','drug_class'=>'Calcium-magnesium-phosphorus mineral combination with B-complex vitamins (veterinary)','uses'=>'A veterinary mineral and vitamin injectable supplying calcium, magnesium, phosphorus compounds and B-group vitamins. It is used to support animals during conditions linked to deficiency of these elements, such as weakness, milk fever, infertility and retarded growth, and as supportive supplementation during convalescence or with poorly nutrient feeds.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml | 300ml | 450ml','desc'=>'Mil-D-Forte Injection contains Calcium, Magnesium and Phosphorus Compounds and vitamins in a well balanced and well tolerated proportions. The said minerals play vital role in the growth and building up resistance against various infections overexertion. The vitamins make up deficiency of Vitamins of B Group and Nicotinamide which is essentially required for convalescence and supplement for poorly nutrient feeds. The deficiency of these elements in animals causes weakness, Milk fever, infertility and retarded growth.'),
  'products/veterinary/injectables/milfon-c-injection' => array('name'=>'Milfon-C Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/milfon-c.png','active'=>'Calcium Gluconate 20.83 g, Magnesium Hypophosphite 5.33 g, Magnesium Chloride 2.00 g, Calcium D-Saccharate 1.00 g, Boric Acid 4.33 g, Dextrose (Anhydrous) 20.00 g (per 100 mL)','composition'=>'Each 100 mL contains: Calcium Gluconate (USP) 20.83 g, Magnesium Hypophosphite 5.33 g, Magnesium Chloride (USP) 2.00 g, Calcium D-Saccharate (USP) 1.00 g, Boric Acid (USP) 4.33 g, Dextrose Anhydrous (USP) 20.00 g, Water for Injection (USP) up to 100 mL (innovator specification).','drug_class'=>'Calcium-magnesium-phosphorus mineral combination (veterinary)','uses'=>'A veterinary calcium and magnesium mineral injectable with dextrose. It is used to support growth and to help maintain animal condition during periods of overexertion or increased mineral demand as part of supportive management.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'300ml | 450ml','desc'=>'Growth and building up resistance against various infectious diseases and overexertion.'),
  'products/veterinary/injectables/milfon-injection' => array('name'=>'Milfon Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/milfon.png','active'=>'Calcium Gluconate 26.60 g, Boric Acid 5.4 g (per 100 mL)','composition'=>'Each 100 mL contains: Calcium Gluconate 26.60 g, Boric Acid 5.4 g.','drug_class'=>'Calcium (calcium gluconate) mineral supplement (veterinary)','uses'=>'A veterinary calcium injectable used to support growth and to help maintain animal condition during periods of overexertion or increased calcium demand as part of supportive care.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'300ml | 450ml','desc'=>'Growth and building up resistance against various infectious diseases and overexertion.'),
