  'products/veterinary/injectables/moxitril-injection-50ml' => array('name'=>'Moxitril Injection 50ml','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/moxitril-50.png','active'=>'Amoxicillin Trihydrate 100 mg, Colistin Sulphate 250,000 IU (per mL)','composition'=>'Each mL contains: Amoxicillin Trihydrate 100 mg, Colistin Sulphate 250,000 IU (as per innovator specification).','drug_class'=>'Antibacterial combination: aminopenicillin (amoxicillin) with polymyxin (colistin)','uses'=>'A veterinary injectable combining two antibacterial agents, amoxicillin and colistin, which act through different mechanisms to provide a broad spectrum of activity against susceptible bacteria. It is used in animals for the management of bacterial infections caused by organisms sensitive to this combination.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml','desc'=>'Amoxicillin Trihydrate + Colistin Sulphate is a combination of two antibiotics. Amoxicillin is a penicillin antibiotic that works by inhibiting bacterial cell wall synthesis, while Colistin is a polymyxin antibiotic that disrupts the cell membrane of bacteria, leading to cell death. The combination of these two antibiotics is used to provide a broad spectrum of antimicrobial activity against a variety of bacteria.'),
  'products/veterinary/injectables/nitoxil-20-injection' => array('name'=>'Nitoxil-20 Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/nitoxil-20.png','active'=>'Nitroxynil 2.0 mg per mL','composition'=>'Each mL contains: Nitroxynil B.P. (Vet) 2.0 mg.','drug_class'=>'Anthelmintic / flukicide (nitrophenol; veterinary)','uses'=>'A veterinary injectable anthelmintic active against liver fluke and gastrointestinal roundworms. It is used in sheep and goats for the management of liver fasciolosis and gastrointestinal nematode infections.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'10ml | 50ml | 100ml','desc'=>'For the treatment of liver fasciolosis, gastrointestinal nematode disease in sheep and goats.'),
