  'products/veterinary/injectables/ocytocin-10-iu-injection-100ml' => array('name'=>'Ocytocin-10 IU Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/ocytocin-10-iu.png','active'=>'Oxytocin 10 IU/ml','composition'=>'Each ml contains: Oxytocin 10 IU (USP Specifications).','drug_class'=>'Posterior pituitary hormone (uterotonic / oxytocic)','uses'=>'A veterinary injectable containing the hormone oxytocin, which promotes contraction of uterine smooth muscle and supports milk let-down from the mammary gland. It is used in obstetric and lactation-related veterinary applications under professional supervision.','route'=>'Parenteral injection','prescription'=>'rx','packs'=>'100ml','desc'=>'Oxytocin is a nonapeptide protein hormone which is produced endogenously in the hypothalamus. Oxytocin promotes contractions of the smooth muscular tissue from the oestrogen sensitised uterus and lacteal gland.'),
