  'products/veterinary/injectables/penci-la-injection' => array('name'=>'Pexcin-LA Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/penci-la.png','active'=>'Benzathine Penicillin G 100,000 IU, Procaine Penicillin G 150,000 IU, Dihydrostreptomycin Sulphate 200 mg (per ml)','composition'=>'Each ml contains: Benzathine Penicillin G 100,000 IU, Procaine Penicillin G 150,000 IU, Dihydrostreptomycin Sulphate 200 mg (innovator specification).','drug_class'=>'Beta-lactam (penicillin) plus aminoglycoside antibacterial combination, long-acting','uses'=>'A long-acting combination veterinary injectable used in the management of susceptible bacterial infections in animals, including respiratory, septicaemic and other systemic conditions caused by organisms sensitive to penicillin or streptomycin. To be used under veterinary supervision.','route'=>'Parenteral injection','prescription'=>'rx','packs'=>'10ml | 20ml | 50ml | 100ml','desc'=>'For the treatment of Pneumonia, Pasteurellosis, Diarrhea, Mastitis, Uteritis, Leptospirosis, Erysipelas, Septicemia and other diseases caused by organism sensitive to penicillin or streptomycin.'),
  'products/veterinary/injectables/pencill-40-injection' => array('name'=>'Pencill-40 Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/pencill-40.png','active'=>'Benzyl Penicillin 1,000,000 IU + Procaine Penicillin 3,000,000 IU','composition'=>'Each vial contains: Benzyl Penicillin 1,000,000 IU, Procaine Penicillin 3,000,000 IU.','drug_class'=>'Beta-lactam (penicillin) antibiotic combination','uses'=>'A veterinary injectable penicillin preparation used in the management of bacterial infections in animals that are susceptible to penicillin. It combines a rapid-acting and a longer-acting penicillin form. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'30ml vial','desc'=>'Treat bacterial infections like strep throat, ear infections and urinary tract infections.'),
  'products/veterinary/injectables/penivet-2-5gm-injection' => array('name'=>'Penivet 2.5gm Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/penivet-2.5','active'=>'Benzyl Penicillin 500,000 IU + Procaine Penicillin 1,500,000 IU + Streptomycin Sulphate 2.5 g','composition'=>'Each vial contains: Benzyl Penicillin 500,000 IU, Procaine Penicillin 1,500,000 IU, Streptomycin Sulphate 2.5 g (Innovator Specification).','drug_class'=>'Penicillin (beta-lactam) plus aminoglycoside antibiotic combination','uses'=>'A veterinary injectable combination of penicillins with the aminoglycoside streptomycin, used in the management of bacterial infections in animals caused by susceptible organisms. The combination provides activity against a broader range of bacteria. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'2.5gm','desc'=>'To treat and prevent certain infections caused by bacteria.'),
  'products/veterinary/injectables/penivet-5-injection' => array('name'=>'Penivet-5 Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/penivet-5.png','active'=>'Benzyl Penicillin 500,000 IU + Procaine Penicillin 1,500,000 IU + Streptomycin Sulphate 5 g','composition'=>'Each vial contains: Benzyl Penicillin 500,000 IU, Procaine Penicillin 1,500,000 IU, Streptomycin Sulphate 5 g (Innovator Specification).','drug_class'=>'Penicillin (beta-lactam) plus aminoglycoside antibiotic combination','uses'=>'A veterinary injectable combination of penicillins with the aminoglycoside streptomycin, used in the management of bacterial infections in animals caused by susceptible organisms. The combined actives broaden the spectrum of antibacterial coverage. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'5gm','desc'=>'To treat and prevent certain infections caused by bacteria.'),
  'products/veterinary/injectables/penivet-forte-injection' => array('name'=>'Penivet Forte Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/penivet-forte.png','active'=>'Penicillin G Procaine 3,000,000 IU + Penicillin G Sodium 1,000,000 IU + Dihydrostreptomycin Sulphate 5 g','composition'=>'Each vial contains: Penicillin G Procaine 3,000,000 IU, Penicillin G Sodium 1,000,000 IU, Dihydrostreptomycin Sulphate 5 g (Innovator Specification).','drug_class'=>'Penicillin (beta-lactam) plus aminoglycoside antibiotic combination','uses'=>'A veterinary injectable combination of procaine and sodium penicillin G with the aminoglycoside dihydrostreptomycin, used in the management of bacterial infections in animals caused by susceptible organisms. The combination offers both rapid and sustained antibacterial activity across a broad range of bacteria. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml vial diluent','desc'=>'To treat and prevent certain infections caused by bacteria.'),
  'products/veterinary/injectables/penivet-injection' => array('name'=>'Penivet Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/penivet.png','active'=>'Procaine Penicillin G 200,000 IU/mL + Dihydrostreptomycin Sulphate 250 mg/mL','composition'=>'Each mL contains: Procaine Penicillin G 200,000 IU, Dihydrostreptomycin Sulphate 250 mg.','drug_class'=>'Penicillin (beta-lactam) plus aminoglycoside antibiotic combination','uses'=>'A veterinary injectable combination of procaine penicillin G with the aminoglycoside dihydrostreptomycin, used in the management of bacterial infections in animals caused by susceptible organisms. The two actives together provide broader antibacterial coverage than either alone. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'100ml','desc'=>'To treat and prevent certain infections caused by bacteria.'),
  'products/veterinary/injectables/penivet-la-injection' => array('name'=>'Penivet LA Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/penivet-la.png','active'=>'Procaine Penicillin G 150,000 IU/mL + Benzathine Penicillin 150,000 IU/mL','composition'=>'Each mL contains: Procaine Penicillin G 150,000 IU, Benzathine Penicillin 150,000 IU.','drug_class'=>'Long-acting beta-lactam (penicillin) antibiotic combination','uses'=>'A long-acting veterinary injectable penicillin preparation combining procaine and benzathine penicillin, used in the management of bacterial infections in animals caused by penicillin-susceptible organisms. The benzathine component provides a prolonged duration of action. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'100ml','desc'=>'To treat and prevent certain infections caused by bacteria.'),
  'products/veterinary/injectables/pred-cpm-injection' => array('name'=>'Pred CPM Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/pred-cpm.png','active'=>'Prednisolone 10 mg/mL + Chlorpheniramine Maleate 4 mg/mL','composition'=>'Each mL contains: Prednisolone 10 mg, Chlorpheniramine Maleate 4 mg.','drug_class'=>'Corticosteroid plus antihistamine combination','uses'=>'A veterinary injectable combining the corticosteroid prednisolone with the antihistamine chlorpheniramine maleate. It is used in the supportive management of inflammatory and allergic conditions in animals. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml | 100ml','desc'=>'Chlorpheniramine Maleate, an antihistamine that mitigates the body\'s response to allergens, and Prednisolone, a corticosteroid that aids in reducing inflammation and itching.'),
  'products/veterinary/injectables/progesteron-injection' => array('name'=>'Progesteron Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/progesteron.png','active'=>'Progesterone 25 mg/mL','composition'=>'Each mL contains: Progesterone 25 mg (USP Specification).','drug_class'=>'Progestogen (steroid sex hormone)','uses'=>'A veterinary injectable progestogen hormone preparation used in reproductive management of animals, including support of endometrial function during early pregnancy in ruminants. It is administered as part of veterinary reproductive programmes. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'10ml | 50ml','desc'=>'Regulating endometrial secretions essential for stimulating and mediating changes in conceptus growth and differentiation throughout early pregnancy in ruminants.'),
  'products/veterinary/injectables/rasomycin-10-injection' => array('name'=>'Rasomycin 10 Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/rasomycin-10.png','active'=>'Oxytetracycline Hydrochloride equivalent to Oxytetracycline base 100 mg/mL','composition'=>'Each mL contains: Oxytetracycline Hydrochloride equivalent to 100 mg Oxytetracycline base.','drug_class'=>'Tetracycline (broad-spectrum bacteriostatic) antibiotic','uses'=>'A broad-spectrum veterinary injectable tetracycline antibiotic with bacteriostatic activity against susceptible gram-positive and gram-negative organisms, as well as rickettsiae, mycoplasma and chlamydia. It is used in the management of bacterial infections in animals caused by susceptible organisms. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'10ml | 50ml | 100ml','desc'=>'Rasomycin is broad spectrum antibiotic with a bacteriostatic action against both gram-positive and gram-negative micro-organisms and furthermore rickettsiae, mycroplasma, chlamydia, some typical mycobacteria and amoebae.'),
  'products/veterinary/injectables/rasomycin-5-injection' => array('name'=>'Rasomycin 5 Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/rasomycin-5.png','active'=>'Oxytetracycline Hydrochloride 50 mg/mL','composition'=>'Each mL contains: Oxytetracycline Hydrochloride 50 mg (USP Specification).','drug_class'=>'Tetracycline (broad-spectrum bacteriostatic) antibiotic','uses'=>'A broad-spectrum veterinary injectable tetracycline antibiotic with bacteriostatic activity against susceptible gram-positive and gram-negative organisms, as well as rickettsiae, mycoplasma and chlamydia. It is used in the management of bacterial infections in animals caused by susceptible organisms. Use should be directed by a qualified veterinarian.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'10 c.c. | 50.c.c/span> 
                                            10ml | 50ml | 100ml','desc'=>'Rasomycin is broad spectrum antibiotic with a bacteriostatic action against both gram-positive and gram-negative micro-organisms and furthermore rickettsiae, mycroplasma, chlamydia, some typical mycobacteria and amoebae. The bacteriostatic effect is based on the inhibition of glutaminic acid metabolism in the cells and synthesis of bacterial proteins.'),
  'products/veterinary/injectables/rasomycin-la-injection' => array('name'=>'Rasomycin LA Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/rasomycin-la.png','active'=>'Oxytetracycline HCl 200 mg/ml','composition'=>'Each ml contains: Oxytetracycline HCl 200 mg (USP Specification).','drug_class'=>'Long-acting tetracycline (broad-spectrum bacteriostatic antibiotic)','uses'=>'A long-acting tetracycline antibiotic injection used in veterinary practice for bacterial infections caused by susceptible gram-positive and gram-negative organisms. It is also active against certain rickettsiae, mycoplasma and chlamydia. To be used under veterinary supervision.','route'=>'Parenteral injection (intramuscular/subcutaneous)','prescription'=>'rx','packs'=>'10ml | 30ml | 50ml | 100ml','desc'=>'Rasomycin is broad spectrum antibiotic with a bacteriostatic action against both gram-positive and gram-negative micro-organisms and furthermore rickettsiae, mycroplasma, chlamydia, some typical mycobacteria and amoebae.'),
  'products/veterinary/injectables/ricomin-injection' => array('name'=>'Ricomin Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/ricomin.png','active'=>'Ricobendazole 100 mg/ml','composition'=>'Each ml contains: Ricobendazole 100 mg.','drug_class'=>'Benzimidazole anthelmintic (broad-spectrum dewormer)','uses'=>'A benzimidazole anthelmintic injection used in livestock against gastrointestinal and pulmonary nematodes, cestodes (tapeworms) and trematodes such as liver fluke (Fasciola hepatica), including adult and immature forms. To be administered under veterinary supervision.','route'=>'Parenteral injection (subcutaneous)','prescription'=>'rx','packs'=>'50ml | 100ml','desc'=>'Acts on eggs sterilization and combats adult and immature forms of gastrointestinal and pulmonary nematodes, cestodes (flat worms) and trematodes (Fasciola hepatica).'),
  'products/veterinary/injectables/ryno-10-injection' => array('name'=>'Ryno 10 Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/ryno-10.png','active'=>'Meloxicam 10 mg/ml','composition'=>'Each ml contains: Meloxicam 10 mg (BP Specifications).','drug_class'=>'Non-steroidal anti-inflammatory drug (NSAID), oxicam class','uses'=>'A non-steroidal anti-inflammatory injection used in animals to relieve pain and inflammation associated with musculoskeletal and arthritic conditions. To be used under veterinary supervision.','route'=>'Parenteral injection (subcutaneous/intravenous)','prescription'=>'rx','packs'=>'100ml vial','desc'=>'To reduce pain from arthritis.'),
  'products/veterinary/injectables/ryno-20-injection' => array('name'=>'Ryno 20 Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/ryno-20.png','active'=>'Meloxicam 20 mg/ml','composition'=>'Each ml contains: Meloxicam 20 mg (BP Specifications).','drug_class'=>'Non-steroidal anti-inflammatory drug (NSAID), oxicam class','uses'=>'A non-steroidal anti-inflammatory injection used in animals to relieve pain and inflammation associated with musculoskeletal and arthritic conditions. To be used under veterinary supervision.','route'=>'Parenteral injection (subcutaneous/intravenous)','prescription'=>'rx','packs'=>'100ml vial','desc'=>'To reduce pain from arthritis.'),
  'products/veterinary/injectables/sanvil-injection' => array('name'=>'Sanvil Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/sanvil.png','active'=>'Pheniramine Maleate 25 mg/ml','composition'=>'Each ml contains: Pheniramine Maleate 25 mg.','drug_class'=>'First-generation antihistamine (H1-receptor antagonist)','uses'=>'An antihistamine injection used in veterinary practice for the management of allergic conditions such as allergic rhinitis, allergic conjunctivitis, skin rashes, serum sickness and other hypersensitivity reactions in animals. To be administered under veterinary supervision.','route'=>'Parenteral injection (intramuscular/intravenous)','prescription'=>'rx','packs'=>'50ml | 100ml','desc'=>'Used to treat allergic conditions, such as hayfever, runny nose, allergic conjunctivitis, rashes, serum sickness, food allergy, vasomotor rhinitis, acute rhinitis, and itching skin conditions,.'),
  'products/veterinary/injectables/spiraline-injection' => array('name'=>'Spiraline Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/spiraline.png','active'=>'Spiramycin (as adipate) 125 mg/ml + Lincomycin HCl 75 mg/ml','composition'=>'Each ml contains: Spiramycin adipate (MS) equivalent to Spiramycin 125 mg and Lincomycin HCl 75 mg.','drug_class'=>'Macrolide (spiramycin) plus lincosamide (lincomycin) antibiotic combination','uses'=>'A combination antibiotic injection used in cattle, sheep, goats and poultry for respiratory tract infections such as pneumonia and mycoplasmosis, as well as soft-tissue, enteric and other susceptible bacterial infections including mastitis and arthritis. To be used under veterinary supervision.','route'=>'Parenteral injection (intramuscular)','prescription'=>'rx','packs'=>'10ml | 50ml | 100ml','desc'=>'For the treatment of respiratory tract infections (RTIs) like pneumonia and mycoplasmosis, soft tissu infections, enteric infections, mastitis nephritis and arthritis in cattle, sheep goat and poultry.'),
  'products/veterinary/injectables/sulpha-s-injection' => array('name'=>'Sulpha-S Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/sulpha-s.png','active'=>'Sulphadimidine Sodium 333.33 mg/ml','composition'=>'Each ml contains: Sulphadimidine Sodium 333.33 mg.','drug_class'=>'Sulfonamide antibacterial','uses'=>'A sulfonamide antibacterial injection used in animals for infections of the urinary, respiratory and gastrointestinal tracts and other infections caused by susceptible organisms, including coccidiosis. To be administered under veterinary supervision.','route'=>'Parenteral injection (intravenous/intramuscular)','prescription'=>'rx','packs'=>'100ml | 300ml | 500ml','desc'=>'Treating uncomplicated infections of the urinary tract, infections caused by Nocardia asteroids, streptococcal pharyngitis, menigococcal diseases, toxoplasmosis, and others.'),
  'products/veterinary/injectables/sulphadimidine-injection' => array('name'=>'Sulphadimidine Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/sulphadimidine.png','active'=>'Sulphadimidine Sodium 333 mg/ml','composition'=>'Each ml contains: Sulphadimidine Sodium 333 mg (BP Vet Specification).','drug_class'=>'Sulfonamide antibacterial','uses'=>'A sulfonamide antibacterial injection active against a range of gram-positive and gram-negative organisms in animals, used for susceptible bacterial and coccidial infections. It acts by interfering with bacterial folic acid synthesis. To be used under veterinary supervision.','route'=>'Parenteral injection (intravenous/intramuscular)','prescription'=>'rx','packs'=>'100ml | 110ml | 500ml','desc'=>'Sulfadimidine acts usually bactericidal against many Gram-positive and Gram-negative microorganisms, like Corynebacterium, E.coli, Eimeria, Fusobacterium necrophorum, Pasteurella, Salmonella and Streptococcus spp. Sulfadimidine affect bacterial purine synthesis, as a result of which a blockade is accomplished.'),
  'products/veterinary/injectables/thiaprin-injection' => array('name'=>'Thiaprin Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/thiaprin.png','active'=>'Vitamin B1 (HCl) 5 mg, Vitamin B2 sodium phosphate 205 mg, Vitamin B6 (HCl) 2.5 mg, Nicotinamide 37.5 mg (per ml)','composition'=>'Each ml contains: Vitamin B1 (HCl) 5 mg, Vitamin B2 sodium phosphate 205 mg, Vitamin B6 (HCl) 2.5 mg and Nicotinamide 37.5 mg.','drug_class'=>'B-complex vitamin supplement','uses'=>'A B-complex vitamin injection used as a nutritional supplement in domestic animals to support metabolism and intestinal flora, particularly during periods of stress, illness or after prolonged antibiotic therapy. To be administered under veterinary supervision.','route'=>'Parenteral injection (intramuscular/subcutaneous)','prescription'=>'rx','packs'=>'10ml | 20ml | 30ml | 50ml | 100ml','desc'=>'Thiaprin Injection is a very important biocatalyst which improves the production, performance and strength of intestinal bacterial flora damaged by prolonged antibiotic treatment. It is also useful for all domestic animals during the periods of stress and disease.'),
  'products/veterinary/injectables/tilmisin-30-injection' => array('name'=>'Tilmisin 30% Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/tilmisin-30.png','active'=>'Tilmicosin (as phosphate) 300 mg/ml','composition'=>'Each ml contains: Tilmicosin as phosphate 300 mg (as per innovator\'s specifications).','drug_class'=>'Macrolide antibiotic','uses'=>'A macrolide antibiotic injection used in cattle and sheep for respiratory infections associated with Mannheimia haemolytica, Pasteurella species and other tilmicosin-susceptible organisms, and for ovine mastitis associated with susceptible organisms. To be administered under veterinary supervision.','route'=>'Parenteral injection (subcutaneous)','prescription'=>'rx','packs'=>'50ml','desc'=>'It is indicated for the treatment of respiratory infections in cattle and sheep associated with Mannheimia haemolytica, Pasteurella spp. and other tilmicosin-susceptible micro-organisms, and for the treatment of ovine mastitis associated with Staphylococcus aureus and Mycoplasma spp.'),
  'products/veterinary/injectables/trisolizin-injection' => array('name'=>'Trisolizin Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/trisolizin.png','active'=>'Trimethoprim 80 mg + Sulphadiazine 400 mg (per ml)','composition'=>'Each ml contains: Trimethoprim 80 mg, Sulphadiazine 400 mg.','drug_class'=>'Potentiated sulfonamide antibacterial (diaminopyrimidine + sulfonamide combination)','uses'=>'A veterinary injectable antibacterial combination of trimethoprim and sulphadiazine intended for the management of susceptible bacterial infections in calves, cattle, cows, goats, sheep and poultry. It is administered under veterinary supervision.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'10ml | 50ml | 100ml','desc'=>'It is used for the treatment of bacterial infections in Calves, Cattle, Cows, Goats, Poultry and Sheep.'),
  'products/veterinary/injectables/tylomac-20-injection' => array('name'=>'Tylomac-20 Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/tylomac-20.png','active'=>'Tylosin (as Tartrate) 200 mg (per ml)','composition'=>'Each ml contains: Tylosin (as Tartrate) 200 mg (USP Specification).','drug_class'=>'Macrolide antibiotic','uses'=>'A veterinary macrolide antibiotic injection used to manage susceptible bacterial and mycoplasmal infections, including respiratory conditions in poultry and livestock. It is administered parenterally under veterinary supervision.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml | 100ml','desc'=>'Tylomac-20 is a macrolide type of antibiotic having a large spectrum of activity gram-positive micro organisms. P.P.L.O, Some spirochetes hemophilus pertussis, erysipelothrix insidosia vibrio coli,moraxella bovis, some aviair coccidia and large viruses synovitis, sinusitis and omithosis in poultry. After parenteral administration therapeutic active blood concentrations of tylomac-20 are reached within 2 hours and maximum concetrations after 4 – 5 hours. The therapeutic blood levels are maintained for about 10 hours after the administration.'),
  'products/veterinary/injectables/tylomac-plus-injection' => array('name'=>'Tylomac Plus Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/tylomac-plus.png','active'=>'Tylosin (as Tartrate) 200 mg (per ml)','composition'=>'Each ml contains: Tylosin (as Tartrate) 200 mg (USP Specification).','drug_class'=>'Macrolide antibiotic','uses'=>'A veterinary macrolide antibiotic injection intended for the management of susceptible bacterial and mycoplasmal infections in livestock. It is administered parenterally under veterinary supervision.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml | 100ml','desc'=>'To treat susceptible infections in livestock.'),
  'products/veterinary/injectables/tystar-injection' => array('name'=>'Tystar Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/tystar.png','active'=>'Tylosin (as Tartrate) 100 mg + Gentamicin (as Sulphate) 50 mg (per ml)','composition'=>'Each ml contains: Tylosin (as Tartrate) 100 mg, Gentamicin (as Sulphate) 50 mg (as per Innovator\'s specifications).','drug_class'=>'Combination antibiotic (macrolide + aminoglycoside)','uses'=>'A veterinary injectable combination of the macrolide tylosin and the aminoglycoside gentamicin intended for the management of susceptible bacterial and mycoplasmal infections in livestock. It is administered parenterally under veterinary supervision.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml','desc'=>'Gentamicin is an aminoglycoside antibiotic indicated for the treatment of a variety of bacterial infections. it is normally used as the sulphate salt. in veterinary medicine gentamicin is used mainly as a solution for injection for sheep cattle and horses and as an oral solution for poultry. Tylosin is an antibiotic from macrolide group. to date tylosin tartrate is known to be the best remedy against mycoplasmosis. at higher dosed, it also acts against gram positive and gram-negative bacteria.k.'),
  'products/veterinary/injectables/vitaden-injection' => array('name'=>'Vitaden Injection','segment'=>'Veterinary','form'=>'Injectables','img'=>'img/product/veterinary/injectables/vitaden.png','active'=>'Vitamin A (Palmitate) 100,000 IU + Vitamin D3 (Cholecalciferol) 100,000 IU + Vitamin E (Alpha-tocopheryl Acetate) 50 mg (per ml)','composition'=>'Each ml contains: Vitamin A (Palmitate) 100,000 IU, Vitamin D3 (Cholecalciferol) 100,000 IU, Vitamin E (Alpha-tocopheryl Acetate) 50 mg.','drug_class'=>'Fat-soluble vitamin supplement (Vitamins A, D3 and E)','uses'=>'A veterinary injectable supplement combining vitamins A, D3 and E to support normal vitamin status in animals. Vitamin A supports mucous membrane integrity, vitamin D3 supports calcium and phosphorus metabolism, and vitamin E acts as an antioxidant. It is administered parenterally under veterinary supervision.','route'=>'Parenteral (injection)','prescription'=>'rx','packs'=>'50ml | 100ml','desc'=>'Vitaden Injection is well known combination of vitamin A, Vitamin D3 and Vitamin E. Thus vitamin A plays an important role in the protection of the mucous membrane subsequently against general infection. Vitamin D3 takes care for a regular process of the calcium phosphorus metabolism and vitamin E acts as antioxidant in the cellular oxygen reduction and in the fat metabolism. Further Vitamins E helps to maintain the stability of vitamin A. After injection the vitamin are quickly and completely absorbed and produce a rapid therapeutic effect. Vitaden injection has a long lasting prophylactic action due to the high concentration of vitamin A and vitamin E.'),
  'products/veterinary/liquid-dosage-form/albaclos-drench' => array('name'=>'Albaclos Drench','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/albados-drench.jpg','active'=>'Albendazole 10 g + Closantel 2 g (per 100 ml)','composition'=>'Each 100 ml contains: Albendazole 10 g, Closantel 2 g.','drug_class'=>'Anthelmintic combination (benzimidazole + salicylanilide flukicide)','uses'=>'A veterinary oral anthelmintic drench combining albendazole and closantel intended for the control of susceptible gastrointestinal worms, lungworms and liver flukes in animals. It is administered orally under veterinary supervision.','route'=>'Oral (drench)','prescription'=>'rx','packs'=>'100ml | 500ml | 1000ml','desc'=>'To treat capillariasis caused by Capillaria plica (dogs and cats) and C. felis cati (cats).'),
  'products/veterinary/liquid-dosage-form/alvenax-10-drench' => array('name'=>'Alvenax 10% Drench','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/alvenax-10-drench.jpg','active'=>'Albendazole 10 mg (per ml)','composition'=>'Each ml contains: Albendazole 10 mg.','drug_class'=>'Benzimidazole anthelmintic','uses'=>'A veterinary oral anthelmintic drench containing albendazole intended for the control of susceptible gastrointestinal worms, tapeworms and liver flukes in livestock. It is administered orally under veterinary supervision.','route'=>'Oral (drench)','prescription'=>'rx','packs'=>'100ml | 150ml | 300ml | 500ml | 1000ml','desc'=>'To treat neurocysticercosis, an infection of the nervous system caused by pork tapeworms.'),
  'products/veterinary/liquid-dosage-form/alvenax-15-drench' => array('name'=>'Alvenax 15% Drench','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/alvenax-15-drench.jpg','active'=>'Albendazole 150 mg (per ml)','composition'=>'Each ml contains: Albendazole 150 mg.','drug_class'=>'Benzimidazole anthelmintic','uses'=>'A veterinary oral anthelmintic drench containing albendazole intended for the control of susceptible gastrointestinal worms, tapeworms and liver flukes in livestock. It is administered orally under veterinary supervision.','route'=>'Oral (drench)','prescription'=>'rx','packs'=>'100ml | 250ml | 500ml | 1000ml','desc'=>'To treat neurocysticercosis, an infection of the nervous system caused by pork tapeworms.'),
  'products/veterinary/liquid-dosage-form/alvenax-2-5-drench' => array('name'=>'Alvenax 2.5% Drench','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/alvenax-2.5-drench.jpg','active'=>'Albendazole 25 mg (per ml)','composition'=>'Each ml contains: Albendazole 25 mg.','drug_class'=>'Benzimidazole anthelmintic','uses'=>'A veterinary oral anthelmintic drench containing albendazole intended for the control of susceptible gastrointestinal worms, tapeworms and liver flukes in livestock. It is administered orally under veterinary supervision.','route'=>'Oral (drench)','prescription'=>'rx','packs'=>'100ml | 150ml | 300ml | 500ml | 1000ml','desc'=>'To treat neurocysticercosis, an infection of the nervous system caused by pork tapeworms.'),
  'products/veterinary/liquid-dosage-form/alvenax-drench' => array('name'=>'Alvenax Drench','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/alvenax-drench.jpg','active'=>'Albendazole 23 mg (per ml, w/v)','composition'=>'Each ml contains: Albendazole 23 mg (w/v).','drug_class'=>'Benzimidazole anthelmintic','uses'=>'A veterinary oral anthelmintic drench containing albendazole intended for the control of susceptible gastrointestinal worms, tapeworms and liver flukes in livestock. It is administered orally under veterinary supervision.','route'=>'Oral (drench)','prescription'=>'rx','packs'=>'100ml | 300ml | 500ml | 1000ml','desc'=>'To treat neurocysticercosis (infection caused by the pork tapeworm in the muscles, brain, and eyes that may cause seizures, brain swelling, and vision problems).'),
  'products/veterinary/liquid-dosage-form/alvenax-sc-liquid' => array('name'=>'Alvenax SC Liquid','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/alvenax-sc-drench.jpg','active'=>'Albendazole 25 mg, Cobalt Chloride 0.75 mg and Sodium Selenite 0.35 mg (per ml)','composition'=>'Each ml contains: Albendazole 25 mg, Cobalt Chloride 0.75 mg, Sodium Selenite 0.35 mg.','drug_class'=>'Benzimidazole anthelmintic with supplementary trace elements (cobalt and selenium)','uses'=>'A veterinary oral anthelmintic preparation that combines albendazole with the trace elements cobalt and selenium. It is used in the management of gastrointestinal and lung nematode infestations and certain cestode and adult liver fluke infections in livestock, while supplying supplementary cobalt and selenium. Administer under veterinary supervision.','route'=>'Oral (drench)','prescription'=>'rx','packs'=>'100ml | 250ml | 500ml | 1000ml','desc'=>'Active against most nematode and some cestode worms including tapeworms and adult liver fluke.'),
  'products/veterinary/liquid-dosage-form/bivamisol-oral-suspension' => array('name'=>'Bivamisol Oral Suspension','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/bivamisol-oral-suspension.jpg','active'=>'Bithionol Sulfoxide 100 g and Levamisole HCl 15 g (per 1000 ml)','composition'=>'Each 1000 ml contains: Bithionol Sulfoxide 100 g, Levamisole HCl 15 g.','drug_class'=>'Combination anthelmintic (salicylanilide-type flukicide with imidazothiazole nematocide)','uses'=>'A veterinary oral anthelmintic suspension combining bithionol sulfoxide and levamisole. It is used as a broad-spectrum dewormer to support the control of fluke and nematode worm burdens in cattle, sheep, goats, pigs and poultry. Use under veterinary direction.','route'=>'Oral','prescription'=>'rx','packs'=>'150ml | 500ml | 1000ml','desc'=>'Used as a nematocidal anthelmintic in cattle, sheep, goats, pigs and poultry.'),
  'products/veterinary/liquid-dosage-form/blotaryl-liquid' => array('name'=>'Blotaryl Liquid','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/blotaryl-liquid.jpg','active'=>'Polyoxyethylene Oleic Acid Triglyceride 10 ml (per vial)','composition'=>'Each 10 ml vial contains: Polyoxyethylene Oleic Acid Triglyceride 10 ml.','drug_class'=>'Antifoaming / surfactant antibloat agent','uses'=>'A veterinary surfactant-based antifoaming preparation. It is used to help relieve frothy bloat and associated smooth-muscle distension of the rumen caused by accumulation of gas in ruminants. Use under veterinary supervision.','route'=>'Oral (intraruminal)','prescription'=>'rx','packs'=>'10ml vial | 25ml vial in box','desc'=>'Elevates smooth muscles spasm precipitated by accumulation of gases.'),
  'products/veterinary/liquid-dosage-form/ceriflox-oral-solution' => array('name'=>'Ceriflox Oral Solution','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/ceriflox-oral-solution.jpg','active'=>'Enrofloxacin 10 g (per 100 ml)','composition'=>'Each 100 ml contains: Enrofloxacin 10 g (Innovator specification).','drug_class'=>'Fluoroquinolone antibacterial','uses'=>'A veterinary oral fluoroquinolone antibacterial solution. It is used in the management of infections caused by susceptible bacteria across a range of animal species, including skin and soft-tissue and urinary-tract infections. Administer under veterinary direction.','route'=>'Oral','prescription'=>'rx','packs'=>'100ml | 500ml | 1000ml','desc'=>'To susceptible bacteria in a variety of species. Treatment has included infections of skin and soft tissue, urinary tract infections in dogs and cats, Chlamydophila felis infections in cats.'),
  'products/veterinary/liquid-dosage-form/cypothrin-pour-on' => array('name'=>'Cypothrin Pour-On','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/cypothrin-pour-on.jpg','active'=>'Cypermethrin 20 g (per 100 ml)','composition'=>'Each 100 ml contains: Cypermethrin 20 g.','drug_class'=>'Synthetic pyrethroid ectoparasiticide / insecticide','uses'=>'A veterinary pour-on pyrethroid ectoparasiticide. It is used for the external control of ticks, mites, lice, flies and other harmful insects on cattle, sheep, goats, horses, camels, poultry and other animals, and to help protect livestock housing. For external use under veterinary guidance.','route'=>'Topical (pour-on)','prescription'=>'rx','packs'=>'100ml | 500ml | 1000ml','desc'=>'For disinsection and deacarization of cattle, sheep, goats, horses, donkeys, camels, poultry and other animals, protection of livestock facilities from harmful insects and ticks.'),
  'products/veterinary/liquid-dosage-form/cypothrin-solution-10' => array('name'=>'Cypothrin Solution 10%','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/cypothrin-solution-10.jpg','active'=>'Cypermethrin 100 g (per 1000 ml)','composition'=>'Each 1000 ml contains: Cypermethrin 100 g.','drug_class'=>'Synthetic pyrethroid ectoparasiticide / insecticide','uses'=>'A veterinary pyrethroid ectoparasiticide concentrate for external use. It is used to help control ticks and biting and nuisance insects on livestock and to protect animal housing and facilities. For external application under veterinary guidance.','route'=>'Topical (external, dip/spray)','prescription'=>'rx','packs'=>'250ml | 500ml | 1000ml','desc'=>'For disinsection and deacarization of cattle, sheep, goats, horses, donkeys, camels, poultry and other animals, protection of livestock facilities from harmful insects and ticks.'),
  'products/veterinary/liquid-dosage-form/delton-2-5-solution' => array('name'=>'Delton 2.5% Solution','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/delton-2.5-solution.jpg','active'=>'Deltamethrin 25 mg (per ml)','composition'=>'Each ml contains: Deltamethrin 25 mg (BP specification).','drug_class'=>'Synthetic pyrethroid ectoparasiticide / insecticide','uses'=>'A veterinary pyrethroid ectoparasiticide solution for external use. It is used to help control ticks, mites, lice and flies on livestock and dogs and around farm premises. For external application under veterinary guidance.','route'=>'Topical (external, dip/spray)','prescription'=>'rx','packs'=>'1L','desc'=>'For control of ticks, mites, lice and flies of livestock, dogs and farm houses.'),
  'products/veterinary/liquid-dosage-form/dipsol-15-solution' => array('name'=>'Dipsol 15% Solution','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/dipsol-15-solution.jpg','active'=>'Diazinon 150 mg (per ml)','composition'=>'Each ml contains: Diazinon 150 mg.','drug_class'=>'Organophosphate ectoparasiticide / insecticide','uses'=>'An organophosphate insecticidal/acaricidal solution. It is used to help control pest insects and external parasites in agricultural and livestock settings, including treatment of soil, ornamental plants and field crops. For external/environmental use only, following veterinary or label guidance.','route'=>'Topical / external (dip, spray)','prescription'=>'rx','packs'=>'250mL | 500mL | 1L | 5L','desc'=>'To control pest insects in soil, on ornamental plants, and on fruit and vegetable field crops.'),
  'products/veterinary/liquid-dosage-form/dipsol-60-solution' => array('name'=>'Dipsol 60% Solution','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/dipsol-60-solution.jpg','active'=>'Diazinon 600 mg (per ml)','composition'=>'Each ml contains: Diazinon 600 mg.','drug_class'=>'Organophosphate ectoparasiticide / insecticide','uses'=>'A concentrated organophosphate insecticidal/acaricidal solution. It is used to help control pest insects and external parasites in agricultural and livestock settings, including treatment of soil, ornamental plants and field crops. For external/environmental use only, following veterinary or label guidance.','route'=>'Topical / external (dip, spray)','prescription'=>'rx','packs'=>'250mL | 500mL | 1L | 5L','desc'=>'To control pest insects in soil, on ornamental plants, and on fruit and vegetable field crops.'),
