  'products/veterinary/liquid-dosage-form/florfenic-20-oral-liquid' => array('name'=>'Florfenic 20% Oral Liquid','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/florfenic-20-oral-liquid.jpg','active'=>'Florfenicol 200 mg (per mL)','composition'=>'Each mL contains: Florfenicol 200 mg (as per innovator\'s specifications).','drug_class'=>'Amphenicol (broad-spectrum) antibiotic','uses'=>'A veterinary antibacterial oral liquid used in cattle for the management of bovine respiratory disease associated with susceptible organisms such as Mannheimia haemolytica, Pasteurella multocida and Histophilus somni. It is also indicated for bovine interdigital phlegmon (foot rot). To be used under veterinary supervision.','route'=>'Oral (in drinking water / oral administration)','prescription'=>'rx','packs'=>'1000mL','desc'=>'For treatment of bovine respiratory disease (BRD) associated with Mannheimia haemolytica, Pasteurella multocida, and Histophilus somni, and for the treatment of bovine interdigital phlegmon (foot rot, acute interdigital necrobacillosis, infectious pododermatitis).'),
