  'products/veterinary/liquid-dosage-form/vermisole-solution' => array('name'=>'Vermisole Solution','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/vermisole-solution.jpg','active'=>'Tetramisole HCl 30 mg (per mL)','composition'=>'Each mL contains: Tetramisole HCl 30 mg.','drug_class'=>'Imidazothiazole anthelmintic (nematicide)','uses'=>'A veterinary oral anthelmintic solution. It is used for the treatment and control of gastrointestinal and pulmonary roundworm (nematode) infestation in livestock. Administer under veterinary guidance.','route'=>'Oral (veterinary)','prescription'=>'rx','packs'=>'500mL | 1000mL','desc'=>'Treats skin infections by killing the infection-causing microorganism.'),
  'products/veterinary/liquid-dosage-form/vernil-plus-solution' => array('name'=>'Vermisole Plus Solution','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/vernil-plus-solution.jpg','active'=>'Levamisole HCl 1.5% w/v + Cobalt Sulphate 0.382% w/v','composition'=>'Each mL contains: Levamisole HCl 15 mg (1.5%), Cobalt Sulphate 3.82 mg (0.382%).','drug_class'=>'Imidazothiazole anthelmintic (nematicide) with supplemental cobalt','uses'=>'A veterinary oral anthelmintic solution combining levamisole with cobalt. It is used for the treatment and control of a range of nematode infestations in domestic animal species and as a microfilaricide in dogs. Use under veterinary supervision.','route'=>'Oral (veterinary)','prescription'=>'rx','packs'=>'100mL | 300mL | 1000mL','desc'=>'For the treatment and control of a range of nematodes in domestic species and as a microfilaricide in dogs.'),
  'products/veterinary/liquid-dosage-form/vernil-sc-drench' => array('name'=>'Vernil SC Drench','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/vernil-sc-solution.jpg','active'=>'Levamisole HCl 1.5 g + Cobalt Sulphate 0.382 g + Sodium Selenite 0.050 g (per 100 mL)','composition'=>'Each 100 mL contains: Levamisole HCl 1.5 g, Cobalt Sulphate 0.382 g, Sodium Selenite 0.050 g.','drug_class'=>'Imidazothiazole anthelmintic (nematicide) with supplemental trace minerals (cobalt and selenium)','uses'=>'A veterinary oral drench containing levamisole with the trace elements cobalt and selenium. Levamisole is active against mature and immature lung worms and gastrointestinal nematodes of cattle, sheep, goats and other animals. Administer as directed by a registered veterinarian.','route'=>'Oral drench (veterinary)','prescription'=>'rx','packs'=>'100mL | 250mL | 500mL | 1000mL','desc'=>'Evamisole is a synthetic anthelmintic. After oral or parenteral administration, it first paralyses the worms and afterwards expel in the faeces. After parenteral application, within 30 minutes maximum blood concentrations are reached and most of the intestinal and lung nematodes are expelled within 24 hours. Levamisole is highly active against mature and immature lung worms and gastrointestinal nematodes of cattle, sheep, goats and other animals. In therapeutic doses Levamisole is nontoxic and no side effects are observed. After double dose restlessness and salivation may be noticed.'),
  'products/veterinary/liquid-dosage-form/vernil-solution' => array('name'=>'Vernil Solution','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/vernil-solution.png','active'=>'Levamisole HCl 15 mg (per mL)','composition'=>'Each mL contains: Levamisole HCl 15 mg.','drug_class'=>'Imidazothiazole anthelmintic (nematicide)','uses'=>'A veterinary oral anthelmintic solution. Levamisole is active against mature and immature lung worms and gastrointestinal nematodes of cattle, sheep, goats and other animals. Use under veterinary supervision.','route'=>'Oral (veterinary)','prescription'=>'rx','packs'=>'100mL | 300mL | 1000mL | 1L','desc'=>'Evamisole is highly active against mature and immature lung worms and gastrointestinal nematodes of cattle, sheep, goats and other animals.'),
  'products/veterinary/liquid-dosage-form/zalvet-plus-suspension' => array('name'=>'Zalvet Plus Suspension','segment'=>'Veterinary','form'=>'Liquid Dosage Forms','img'=>'img/product/veterinary/liquid-dosage-form/zalvet-plus-suspension.jpg','active'=>'Oxyclozanide 34 mg + Sodium Selenite 0.35 mg + Cobalt Chloride 0.75 mg (per mL)','composition'=>'Each mL contains: Oxyclozanide 34 mg, Sodium Selenite 0.35 mg, Cobalt Chloride 0.75 mg.','drug_class'=>'Salicylanilide flukicide (anthelmintic) with supplemental trace minerals (selenium and cobalt)','uses'=>'A veterinary oral anthelmintic suspension combining oxyclozanide with the trace elements selenium and cobalt. It is used for the treatment and control of fascioliasis (liver fluke) in ruminants such as cattle, sheep and goats. Use under veterinary supervision.','route'=>'Oral (veterinary)','prescription'=>'rx','packs'=>'100mL | 250mL | 500mL | 1000mL','desc'=>'It is used in the treatment and control of fascioliasis in ruminants mainly domestic animals such as cattle, sheep, and goats.'),
