  'products/veterinary/semi-solid/mammisol-intramammary-injection' => array('name'=>'Mammisol Intramammary Injection','segment'=>'Veterinary','form'=>'Semi-Solid Forms','img'=>'img/product/veterinary/semi-solid/mammisol-intramammary-injection.jpg','active'=>'Kanamycin Sulphate 51 mg, Dihydrostreptomycin 280 mg, Procaine Penicillin G 200,000 IU, Diphenylsulphone (Dapsone) 550 mg (per 10 g)','composition'=>'Each 10 g contains: Kanamycin Sulphate 51 mg, Dihydrostreptomycin 280 mg, Procaine Penicillin G 200,000 IU, Diphenylsulphone (Dapsone) 550 mg.','drug_class'=>'Combination intramammary antibacterial (aminoglycoside + beta-lactam antibiotics with a sulphone agent)','uses'=>'A veterinary intramammary preparation used in the udder of dairy animals for the management of mastitis associated with susceptible Gram-positive and Gram-negative organisms. It is intended for administration by a veterinarian or under veterinary supervision.','route'=>'Intramammary','prescription'=>'rx','packs'=>'50ml vial','desc'=>'For intra mammary treatment of hovine and gram-negative organisms.'),
  'products/veterinary/semi-solid/mastigon-intramammary-ointment' => array('name'=>'Mastigon Intramammary Ointment','segment'=>'Veterinary','form'=>'Semi-Solid Forms','img'=>'img/product/veterinary/semi-solid/mastigon-intramammary-ointment.jpg','active'=>'Lincomycin (as HCl) 200 mg, Neomycin (as Sulphate) 200 mg, Prednisolone 5 mg (per injector)','composition'=>'Each injector contains: Lincomycin (as HCl) 200 mg, Neomycin (as Sulphate) 200 mg, Prednisolone 5 mg.','drug_class'=>'Combination intramammary antibacterial (lincosamide + aminoglycoside antibiotics) with a corticosteroid','uses'=>'A veterinary intramammary ointment used in dairy animals to support the short-term management of mastitis caused by susceptible bacterial strains. The added corticosteroid component is included to help address local inflammation. It is intended for use under veterinary supervision.','route'=>'Intramammary','prescription'=>'rx','packs'=>'10gm | 4x10gm injector','desc'=>'Short-term treatment of severe infections caused by susceptible strains.'),
  'products/veterinary/solid-dosage-form/alvegest-powder' => array('name'=>'Alvegest Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/alvegest-powder.jpg','active'=>'Calcium Propionate 250 g, Sodium Propionate 400 g, Acetanilide 150 g, Magnesium Oxide 125 g, Sodium Chloride 20 g, Iron Sulphate 400 mg, Zinc Sulphate 100 mg, Magnesium Sulphate 200 mg, Copper Sulphate 450 mg, Cobalt Sulphate 400 mg, Sodium Molybdate 100 mg (per kg)','composition'=>'Each kilogram contains: Calcium Propionate 250 g, Sodium Propionate 400 g, Acetanilide 150 g, Magnesium Oxide 125 g, Sodium Chloride 20 g, Iron Sulphate 400 mg, Zinc Sulphate 100 mg, Magnesium Sulphate 200 mg, Copper Sulphate 450 mg, Cobalt Sulphate 400 mg, Sodium Molybdate 100 mg.','drug_class'=>'Veterinary digestive and mineral supplement (organic acid salts with trace minerals)','uses'=>'An oral powder supplement formulated for ruminants such as cattle, buffalo, sheep and goats. It provides propionate salts together with essential macro- and trace minerals to support digestive function and general nutritional balance in livestock.','route'=>'Oral','prescription'=>'otc','packs'=>'100gm','desc'=>'Appetiser Digestive powder for all ruminant like sheep Goat buffaloe.'),
  'products/veterinary/solid-dosage-form/alvenax-150-bolus' => array('name'=>'Alvenax 150 Bolus','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/alvenax-150-bolus.jpg','active'=>'Albendazole 150 mg','composition'=>'Each bolus contains: Albendazole 150 mg.','drug_class'=>'Benzimidazole broad-spectrum anthelmintic (dewormer)','uses'=>'A veterinary oral bolus containing albendazole, used in livestock for the control of common gastrointestinal nematodes and certain cestodes (tapeworms), and active against adult liver fluke in susceptible animals. It is administered under veterinary guidance as part of a parasite-control programme.','route'=>'Oral','prescription'=>'rx','packs'=>'55 Bolus | 60 Bolus | 65 Bolus','desc'=>'Active against most nematode and some cestode worms including tapeworms and adult liver fluke.'),
