  'products/veterinary/solid-dosage-form/alvenax-2500-bolus' => array('name'=>'Alvenax 2500 Bolus','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/alvenax-2500-bolus.jpg','active'=>'Albendazole 2500 mg','composition'=>'Each bolus contains: Albendazole 2500 mg.','drug_class'=>'Benzimidazole broad-spectrum anthelmintic (dewormer)','uses'=>'A high-strength veterinary oral bolus containing albendazole, used in large livestock for the control of gastrointestinal nematodes, tapeworms and adult liver fluke in susceptible animals. It is administered under veterinary supervision as part of a deworming regimen.','route'=>'Oral','prescription'=>'rx','packs'=>'5’s | 2x5’s | 10x4’s | 10x5’s | 20x1\'s','desc'=>'To treat neurocysticercosis, an infection of the nervous system caused by pork tapeworms.'),
