  'products/veterinary/solid-dosage-form/alvenax-granules' => array('name'=>'Alvenax Granules','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/alvenax-albendazole.png','active'=>'Albendazole 200mg per gram','composition'=>'Each gram contains: Albendazole 200mg.','drug_class'=>'Broad-spectrum benzimidazole anthelmintic (antiparasitic)','uses'=>'A veterinary anthelmintic used to support the management of gastrointestinal and other parasitic worm infestations in animals, including roundworms, hookworms, threadworms, whipworms, pinworms and certain flukes. Administered under veterinary supervision.','route'=>'Oral (in-feed/water granules)','prescription'=>'rx','packs'=>'50x5gm | 100gm | 250gm | 500gm | 1kg | 50gm x 10\'s','desc'=>'To treat infections caused by roundworms, hookworms, threadworm, whipworm, pinworm, flukes, and other parasites.'),
  'products/veterinary/solid-dosage-form/aminovital-powder' => array('name'=>'Aminovital Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/aminovital-powder.jpg','active'=>'Multivitamin and amino acid complex (Vitamins A, D, E, K, B1, B2, B6, B12, C, Folic Acid, Nicotinic Acid, Calcium Pantothenate, Choline, DL-Methionine, L-Lysine Monohydrochloride, Cysteine, Tryptophan, Arginine, Glutamic Acid)','composition'=>'Each 500g contains: Vitamin A 5,000,000 IU, Vitamin D 1,000,000 IU, Vitamin E 6,500 IU, Vitamin K 1,500mg, Vitamin B1 2,000mg, Vitamin B2 1,500mg, Vitamin B6 1,500mg, Vitamin B12 5mg, Vitamin C 20,000mg, Folic Acid 550mg, Nicotinic Acid 25,000mg, Calcium Pantothenate 4,000mg, Choline 10,000mg, DL-Methionine 20,000mg, L-Lysine Monohydrochloride 50,000mg, Cysteine 800mg, Tryptophan 350mg, Arginine 700mg, Glutamic Acid 25,000mg.','drug_class'=>'Water-soluble vitamin and amino acid nutritional supplement','uses'=>'A water-soluble vitamin and amino acid complex used as a nutritional supplement in animals to help address dietary vitamin deficiency and nutritional imbalance. It may be used to support general health and condition, including during dietary transition and periods of environmental stress.','route'=>'Oral (water-soluble powder)','prescription'=>'otc','packs'=>'25 gm | 100gm | 500gm | 1Kg jar | 2.5kg jar','desc'=>'Aminovital is a stable, water soluble, assimilable and well proportioned Vitamin complex. This product provides an efficient control of avitaminosis and nutritional imbalance and facilitates transition from one diet to another. It enables to react against the unfavourable environmental conditions. More-over, it constitutes an indispensable complement during infectious or parasitic disease. Vitamins are vitally required for making up deficiency due to poor nutrient feed. Aminoacids through combined biological processes aids in the maintenance of good health and performance and supports treatment of infectious diseases and helps to overcome stress situations.'),
  'products/veterinary/solid-dosage-form/ascanil-powder' => array('name'=>'Ascanil Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/ascanil-powder.jpg','active'=>'Phenothiazine 270g, Piperazine 140g, Dibutyltin Dilaurate 70g per kg','composition'=>'Each kg contains: Phenothiazine 270g, Piperazine 140g, Dibutyltin Dilaurate 70g.','drug_class'=>'Combination anthelmintic (antiparasitic)','uses'=>'A combination veterinary anthelmintic used to support the control of gastrointestinal worm infestations in animals. Used under veterinary supervision.','route'=>'Oral (in-feed powder)','prescription'=>'rx','packs'=>'100gm | 1Kg | 5kg','desc'=>'to treat serious mental and emotional disorders, including schizophrenia and other psychotic disorders.'),
  'products/veterinary/solid-dosage-form/avitone-powder' => array('name'=>'Avitone Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/avitone-powder.jpg','active'=>'Multivitamin, mineral and amino acid complex (Vitamins A, D, E, K, B1, B2, B6, B12, C, Nicotinic Acid, Folic Acid, Calcium Pantothenate, Copper Sulphate, Zinc, Manganese, Iron, Lysine, Choline)','composition'=>'Each 500g contains: Vitamin A 4,000,000 IU, Vitamin D 1,000,000 IU, Vitamin E 2,000 IU, Vitamin K 300mg, Vitamin B1 300mg, Vitamin B2 1,000mg, Vitamin B6 650mg, Vitamin B12 2.5mg, Nicotinic Acid 5,500mg, Folic Acid 200mg, Calcium Pantothenate 3,000mg, Vitamin C 7,500mg, Sodium Metabisulphite 25mg, Copper Sulphate 750mg, Zinc 5,500mg, Manganese 5,500mg, Iron 5,500mg, Lysine 100mg, Choline 500mg.','drug_class'=>'Water-soluble vitamin, mineral and amino acid nutritional supplement','uses'=>'A water-soluble vitamin, mineral and amino acid complex used as a nutritional supplement in animals to help address dietary vitamin and mineral deficiency and nutritional imbalance. It may be used to support normal growth and general condition, including during dietary transition and environmental stress.','route'=>'Oral (water-soluble powder)','prescription'=>'otc','packs'=>'100gm | 250gm | 500gm','desc'=>'Avitone is a stable, water soluble, assimilable and well proportioned vitamins complex, which provides an efficient control of avitaminosis and nutritional imbalance. Avitone ensures a rapid growth, a maximum and well proportion and facilitates the transition front one diet to another. It enables to react against the unfavourable environmental changes (ie temperature, moisture etc.) moreover it constitutes an indispensable complement during infections or parasitic diseases.'),
  'products/veterinary/solid-dosage-form/bronchez-w-s-powder' => array('name'=>'Bronchez WS Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/bronchez-ws-powder.jpg','active'=>'Tylosin (as Tartrate) 100g, Doxycycline HCl 200g, Colistin Sulphate 500 MIU, Bromhexine HCl 10g per kg','composition'=>'Each kg contains: Tylosin (as Tartrate) 100g, Doxycycline HCl 200g, Colistin Sulphate 500 MIU, Bromhexine HCl 10g.','drug_class'=>'Combination antibacterial (macrolide, tetracycline and polymyxin) with mucolytic','uses'=>'A combination antibacterial and mucolytic preparation used to support the management of susceptible respiratory tract infections in animals. Used under veterinary supervision.','route'=>'Oral (water-soluble powder)','prescription'=>'rx','packs'=>'100gm | 500gm | 1kg','desc'=>'For the treatment of respiratory infections.'),
  'products/veterinary/solid-dosage-form/cera-coli-oral-powder' => array('name'=>'Cera Coli Oral Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/cera-coli-oral-powder.jpg','active'=>'Enrofloxacin 2000mg, Colistin Sulphate 4,500,000 IU per 10g','composition'=>'Each 10g contains: Enrofloxacin 2000mg, Colistin Sulphate 4,500,000 IU.','drug_class'=>'Combination antibacterial (fluoroquinolone and polymyxin)','uses'=>'A combination antibacterial preparation used to support the management of susceptible gastrointestinal, respiratory and urinary tract infections in animals. Used under veterinary supervision.','route'=>'Oral (water-soluble powder)','prescription'=>'rx','packs'=>'10gm','desc'=>'For gastrointestinal, respiratory and urinary tract infections.'),
  'products/veterinary/solid-dosage-form/closan-500mg-bolus' => array('name'=>'Closan 500mg Bolus','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/closan-500-bolus.jpg','active'=>'Closantel (as Sodium) 500mg per bolus','composition'=>'Each bolus contains: Closantel (as Sodium) 500mg.','drug_class'=>'Salicylanilide anthelmintic (flukicide/antiparasitic)','uses'=>'A veterinary anthelmintic used to support the control of adult and immature liver flukes and certain blood-feeding nematodes, as well as larval stages of some arthropod parasites in animals. Used under veterinary supervision.','route'=>'Oral (bolus)','prescription'=>'rx','packs'=>'50gm | 100gm','desc'=>'Reatment and control of adult and immature liver flukes, haematophagous nematodes and larval stages of some arthropods.'),
  'products/veterinary/solid-dosage-form/coccirid-powder' => array('name'=>'Coccirid Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/coccirid-powder.jpg','active'=>'Sulphachlorpyridazine 30g per 100g','composition'=>'Each 100g contains: Sulphachlorpyridazine 30g.','drug_class'=>'Sulphonamide antibacterial','uses'=>'A sulphonamide antibacterial preparation used to support the management of susceptible bacterial infections, including urinary tract infections, in animals. Used under veterinary supervision.','route'=>'Oral (water-soluble powder)','prescription'=>'rx','packs'=>'100gm | 250gm | 500gm | 1kg | 2.5kg','desc'=>'For urinary tract infections.'),
  'products/veterinary/solid-dosage-form/coxifin-powder' => array('name'=>'Coxifin Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/coxifin-powder.jpg','active'=>'Amprolium HCl 200g, Furaltadone HCl 200g, Vitamin A 4,000,000 IU, Vitamin D 2,000,000 IU, Vitamin K3 10g per 1000g','composition'=>'Each 1000g contains: Amprolium HCl 200g, Furaltadone HCl 200g, Vitamin A 4,000,000 IU, Vitamin D 2,000,000 IU, Vitamin K3 10g.','drug_class'=>'Anticoccidial (amprolium) and nitrofuran antibacterial combination with vitamin supplementation','uses'=>'A combination anticoccidial and antibacterial preparation with added vitamins used to support the management of coccidiosis in poultry. Used under veterinary supervision.','route'=>'Oral (in-feed/water powder)','prescription'=>'rx','packs'=>'100gm | 500gm | 1kg | 2.5kg','desc'=>'Amprolium is an antiprotozoal agent and coccidiostatics. It is used for the treatment of enteric coccidiosis. Moreover it is also effective against first generation schizonts of developing coccidia. Vitamin A plays an important role in the protection of mucous membrance and also important for growth and laying eggs. Vitamin D3 takes care for regular process of calcium phosphorus metabolism. Vitamin K3 is essential in poultry particularly to stop haemorrhages.'),
  'products/veterinary/solid-dosage-form/diarroban-powder' => array('name'=>'Diarroban Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/diarroban-powder.jpg','active'=>'Neomycin Sulphate 400mg, Streptomycin Sulphate 400mg, Sulphaguanidine 4g, Kaolin 4g, Pectin 400mg, Bismuth Subnitrate 2g, Vitamin A Acetate 80,000 IU per 12g','composition'=>'Each 12g contains: Neomycin Sulphate 400mg, Streptomycin Sulphate 400mg, Sulphaguanidine 4g, Kaolin 4g, Pectin 400mg, Bismuth Subnitrate 2g, Vitamin A Acetate 80,000 IU.','drug_class'=>'Combination intestinal antibacterial (aminoglycoside and sulphonamide) with adsorbent antidiarrhoeal agents','uses'=>'A combination antibacterial and adsorbent antidiarrhoeal preparation used to support the management of enteric infections and diarrhoea associated with the digestive tract in animals. Used under veterinary supervision.','route'=>'Oral (water-soluble powder)','prescription'=>'rx','packs'=>'20x12gm | 250gm | 1kg | 500gm | 100gm','desc'=>'Antibiotics and antidiarrhoeals with specific action on the digestive tract. Neomycine is very poorly absorbed in the intestines and remains in whole length. Streptomycine is effective against many enteric infections. Sulphaguanidine has a proven practical value as it controls infection for poultry , goats, Sheep. In the higher concentration as in Diarroban powder it has remarkable activity against E.tenella and E.necatrix. Kaoline and pectin are known antidiarrhoeals.'),
  'products/veterinary/solid-dosage-form/dylex-water-soluble' => array('name'=>'Dylex Water Soluble Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/dylex-water-soluble.jpg','active'=>'Trichlorfon 980 mg','composition'=>'Each gram contains: Trichlorfon 980 mg (as per innovator\'s specifications).','drug_class'=>'Organophosphate antiparasitic (anthelmintic/ectoparasiticide)','uses'=>'A veterinary preparation used for the control of internal and external parasites in various animal species. It may be administered orally, topically, or parenterally as directed by a veterinarian.','route'=>'Oral / topical / parenteral (water-soluble powder)','prescription'=>'rx','packs'=>'5gm | 10gm | 100gm | 500gm | 1000gm','desc'=>'It is used orally, topically or parentally for the control of parasites in various animal species.'),
  'products/veterinary/solid-dosage-form/eg-grow-granules' => array('name'=>'Eg-Grow Granules','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/eg-grow-granules.jpg','active'=>'Calcium Lactate, Calcium Phosphate, Calcium Carbonate, Vitamin D2 (Ergocalciferol), Vitamin K3 (Menadione)','composition'=>'Each 500 g contains: Calcium Lactate 300 g, Calcium Phosphate 300 g, Calcium Carbonate 300 g, Vitamin D2 5.32 mg, Vitamin K3 100 mg.','drug_class'=>'Calcium and vitamin (D and K3) mineral/nutritional supplement','uses'=>'A nutritional feed supplement providing calcium salts together with Vitamin D and Vitamin K3 for poultry and other flocks. It supports normal skeletal development, egg-shell formation, and helps address dietary deficiencies of calcium and these vitamins.','route'=>'Oral (granules, in feed or water)','prescription'=>'otc','packs'=>'120gm | 500gm | 1kg','desc'=>'Eg-Grow Granules is combination of three Calcium salts with Vitamin D and Vitamin K3, it accelerates growth, increases egg production and provides protection against poor structural development, low egg production and combats rickets and Osteomalacia. Chickens and other flocks having a Vitamin K3 deficiency suffer from haemorrhages (intra-abdominal haemorrhages, ovarian haemorrhages, cloacal or intestinal haemorrhages etc.) The addition of Vitamin K3 having blood clotting and antihaemorragic action, gives complete protection to poultry.'),
  'products/veterinary/solid-dosage-form/flumine-bolus' => array('name'=>'Flumine Bolus','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/flumine-bolus.jpg','active'=>'Flumequine 350 mg','composition'=>'Each bolus contains: Flumequine 350 mg.','drug_class'=>'Fluoroquinolone (quinolone) antibacterial','uses'=>'A veterinary antibacterial bolus used in the management of enteric (gastrointestinal) infections caused by susceptible organisms in cattle, swine, poultry, and fish.','route'=>'Oral (bolus)','prescription'=>'rx','packs'=>'2x10 Bolus | 5x10 Bolus','desc'=>'Used in veterinarian medicine for the treatment of enteric infections (all infections of the intestinal tract), as well as to treat cattle, swine, chickens, and fish.'),
  'products/veterinary/solid-dosage-form/infadox-water-soluble-powder' => array('name'=>'Infadox Water Soluble Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/infadox-water-souble-powder.jpg','active'=>'Tylosin (as Tartrate) 100 mg, Doxycycline HCl 200 mg','composition'=>'Each gram contains: Tylosin (as Tartrate) 100 mg, Doxycycline HCl 200 mg (as per innovator\'s specifications).','drug_class'=>'Macrolide (tylosin) and tetracycline (doxycycline) antibacterial combination','uses'=>'A veterinary antibacterial combination used in the management of gastrointestinal and respiratory infections caused by tylosin- and doxycycline-susceptible organisms in calves, goats, poultry, sheep, and swine.','route'=>'Oral (water-soluble powder, in drinking water)','prescription'=>'rx','packs'=>'100gm | 500gm | 1kg','desc'=>'Gastrointestinal and respiratory infections caused by tylosin and doxycycline sensitive micro-organisms, like Bordetella, Campylobacter, Chlamydia, E. coli, Haemophilus, Mycoplasma, Pasteurella, Rickettsia, Salmonella, Staphylococcus, Streptococcus and Treponema spp. in calves, goats, poultry, sheep and swine.'),
  'products/veterinary/solid-dosage-form/lefastar-20-powder' => array('name'=>'Lefastar 20% Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/lefastar-20-powder.jpg','active'=>'Levamisole HCl 200 mg per gram (20% w/w)','composition'=>'Each gram contains: Levamisole HCl B.P. 200 mg (manufacturer\'s specifications).','drug_class'=>'Imidazothiazole anthelmintic (dewormer)','uses'=>'A veterinary anthelmintic used for the control of lungworms and gastrointestinal nematodes (roundworms) in animals.','route'=>'Oral (water-soluble powder)','prescription'=>'rx','packs'=>'100gm | 500gm | 1000gm | 2.5kg','desc'=>'Effective against lungworms and gastrointestinal nematodes.'),
  'products/veterinary/solid-dosage-form/levapoul-ws-powder' => array('name'=>'Levapoul W.S. Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/levapoul-ws-powder.jpg','active'=>'Levamisole HCl 15% w/w (150 mg per gram)','composition'=>'Each 100 g contains: Levamisole HCl 15% w/w (as per innovator\'s specifications).','drug_class'=>'Imidazothiazole anthelmintic (dewormer)','uses'=>'A water-soluble veterinary anthelmintic used for the control of lungworms and gastrointestinal nematodes (roundworms) in animals and poultry.','route'=>'Oral (water-soluble powder, in drinking water)','prescription'=>'rx','packs'=>'100gm | 500gm | 1kg','desc'=>'Effective against lungworms and gastrointestinal nematodes.'),
  'products/veterinary/solid-dosage-form/levozan-bolus' => array('name'=>'Levozan Bolus','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/levozan.png','active'=>'Levamisole HCl 1125 mg, Oxyclozanide 2225 mg','composition'=>'Each bolus contains: Levamisole HCl 1125 mg, Oxyclozanide 2225 mg.','drug_class'=>'Anthelmintic combination (imidazothiazole nematicide with salicylanilide flukicide)','uses'=>'A veterinary anthelmintic bolus used in the control of mixed parasitic infections, including roundworms, lungworms, and liver flukes, in ruminants.','route'=>'Oral (bolus)','prescription'=>'rx','packs'=>'5bolus | 10bolus(2x5) | 50bolus(5x10)','desc'=>'To treat infections caused by roundworms, lungworms, and flukes.'),
  'products/veterinary/solid-dosage-form/neo-oxy-30-powder' => array('name'=>'Neo-Oxy 30 Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/neo-oxy-30-powder.jpg','active'=>'Oxytetracycline HCl 15 g, Neomycin Sulphate 15 g (per 450 g)','composition'=>'Each 450 g contains: Oxytetracycline HCl 15 g, Neomycin Sulphate 15 g.','drug_class'=>'Broad-spectrum antibacterial combination (tetracycline with aminoglycoside)','uses'=>'A broad-spectrum veterinary antibacterial powder used in the management of respiratory, gastrointestinal, and urinary tract infections of gram-positive and gram-negative origin in cattle, sheep, goats, and dogs.','route'=>'Oral (powder)','prescription'=>'rx','packs'=>'125gm | 450gm','desc'=>'Sheep, cattle, dogs & goats: broad spectrum, high potency antibiotic for respiratory tract, g.i. Tract & urinary tract infections of gram positive and gram negative origin including certain fungi and protozoal infections.'),
  'products/veterinary/solid-dosage-form/neovit-super-powder' => array('name'=>'Neovit Super Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/neovit-super-powder.jpg','active'=>'Oxytetracycline HCl 55.56 mg, Neomycin Sulphate 38.89 mg, Vitamin A Acetate 1111.11 IU, Vitamin D3 222.22 IU, Vitamin B12 4.4 mcg, Nicotinamide 8.89 mg, Calcium D-Pantothenate 3.33 mg (per gram)','composition'=>'Each gram contains: Oxytetracycline HCl 55.56 mg, Neomycin Sulphate 38.89 mg, Vitamin A Acetate 1111.11 IU, Vitamin D3 222.22 IU, Vitamin B12 4.4 mcg, Nicotinamide 8.89 mg, Calcium D-Pantothenate 3.33 mg.','drug_class'=>'Broad-spectrum antibacterial (tetracycline + aminoglycoside) with multivitamin combination','uses'=>'A veterinary combination powder providing broad-spectrum antibacterial coverage against gram-positive and gram-negative organisms together with a vitamin complex. It is used to support animals during bacterial challenge and to help address nutritional imbalance and vitamin deficiency in poultry and livestock.','route'=>'Oral (water-soluble powder, in feed or water)','prescription'=>'rx','packs'=>'100gm | 180gm | 250gm | 500gm | 5kg','desc'=>'Oxytetracycline HC1 and Neomycine Sulphate is a well balanced combination of the board spectrum antibiotic having efficiency against mainly all gram-positive and gram¬negative micro-organism. The penetration of oxytetracycline into the body is very good producing highly active concentration in blood and tissue. Neomycine is absorbed very poorly from the intestinal tract and therefore remain active in the whole length of intestines. In Neovit Super Powder: stable, water soluble, assimilable and proportioned Vitamin complex have been added, which provides an efficient control of avitaminosis and nutritional imbalance. Neovit super powder ensures a rapid growth, a maximum egg and meat production and facilitates the transition from one diet to another.'),
  'products/veterinary/solid-dosage-form/neozone-pessaries' => array('name'=>'Neozone Pessaries','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/neozone-pessaries.jpg','active'=>'Neomycin Sulphate 1000 mg, Nitrofurazone 100 mg','composition'=>'Each pessary contains: Neomycin Sulphate 1000 mg, Nitrofurazone 100 mg.','drug_class'=>'Topical antibacterial combination (aminoglycoside with nitrofuran)','uses'=>'A veterinary intrauterine antibacterial preparation used in the prevention and management of bacterial infections of the genital tract in cows, buffaloes, and mares.','route'=>'Intrauterine / intravaginal (pessary)','prescription'=>'rx','packs'=>'10\'s | 30\'s | 50\'s | 100\'s','desc'=>'For the prevention and treatment of general bacterial infections of genital tract in cow buffaloes and mares.'),
  'products/veterinary/solid-dosage-form/niczole-tablets' => array('name'=>'Niczole Tablets','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/niczole-tablet.jpg','active'=>'Niclosamide 33.70 mg + Oxibendazole 3.80 mg','composition'=>'Each tablet contains: Niclosamide 33.70 mg, Oxibendazole 3.80 mg.','drug_class'=>'Anthelmintic combination (salicylanilide cestocide with benzimidazole nematocide)','uses'=>'A veterinary anthelmintic indicated for the management of tapeworm and intestinal fluke infections in animals. It combines two complementary deworming agents to address gastrointestinal parasites. To be used under veterinary supervision.','route'=>'Oral','prescription'=>'rx','packs'=>'24\'s | 48\'s','desc'=>'For the treatment of tapeworm and intestinal fluke infections.'),
  'products/veterinary/solid-dosage-form/nizam-bolus' => array('name'=>'Nizam Bolus','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/nizam-bolus.jpg','active'=>'Levamisole HCl 1000 mg + Oxyclozanide 1400 mg','composition'=>'Each bolus contains: Levamisole HCl 1000 mg, Oxyclozanide 1400 mg.','drug_class'=>'Anthelmintic combination (imidazothiazole nematocide with salicylanilide flukicide)','uses'=>'A veterinary anthelmintic bolus used to manage infections caused by roundworms, lungworms and liver flukes in livestock. The combination provides broad-spectrum activity against gastrointestinal and respiratory nematodes together with adult flukes. To be administered under veterinary guidance.','route'=>'Oral','prescription'=>'rx','packs'=>'5\'s | 10\'s | 48\'s | 55\'s | 60\'s','desc'=>'To treat infections caused by roundworms, lungworms, and flukes.'),
  'products/veterinary/solid-dosage-form/nutramin-powder' => array('name'=>'Nutramin Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/nutramin-powder.png','active'=>'Multiminerals (Calcium, Phosphorus, Magnesium, Sodium, Iron, Manganese, Copper, Cobalt, Iodine, Selenium)','composition'=>'Each kg contains: Calcium 15.4%, Phosphorus 13.5%, Magnesium 5.5%, Sodium 1000 mg, Iron 3000 mg, Manganese 2000 mg, Copper 600 mg, Cobalt 10 mg, Iodine 40 mg, Selenium 3 mg.','drug_class'=>'Mineral and trace-element nutritional supplement','uses'=>'A balanced mineral feed supplement formulated to help meet the macro-mineral and trace-element requirements of livestock. It supports general nutritional needs where dietary mineral intake may be inadequate. Intended as a feed additive for animal use.','route'=>'Oral (in-feed)','prescription'=>'otc','packs'=>'1kg | 2.5kg | 5kg | 10kg | 50kg','desc'=>'The scientific research has revealed that the living body and its parts and minerals contained in animal feed are composed of similar elements in their descriptions, the deficiency of which causes various diseases. NUTRAMIN POWDER is a well balanced combination of essential minerals which not only helps the livestock to combat the diseases but also increases production with milk and meat.'),
  'products/veterinary/solid-dosage-form/nutravet-powder' => array('name'=>'Nutravet Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/nutravet-powder.jpg','active'=>'Multivitamins with minerals and trace elements (Vitamins A, D3, E, B1, B2, B6, B12, D-Pantothenic acid, Niacin, Folic acid, Biotin; Iron, Zinc, Manganese, Copper, Iodine, Selenium)','composition'=>'Each kg contains: Vitamin A 4,000,000 IU, Vitamin D3 500,000 IU, Vitamin E 12,500 IU, Vitamin B1 1000 mg, Vitamin B2 2000 mg, Vitamin B6 500 mg, D-Pantothenic acid 4000 mg, Niacin 5000 mg, Folic acid 50 mg, Biotin 25 mg, Vitamin B12 10 mg, Butylhydroxytoluene 50,000 mg, Iron 10,000 mg, Zinc 10,000 mg, Manganese 15,000 mg, Copper 2500 mg, Iodine 50 mg, Selenium 25 mg.','drug_class'=>'Vitamin, mineral and trace-element nutritional supplement','uses'=>'A combined vitamin and mineral feed supplement intended to help support adequate nutrient intake during demanding periods such as growth, vaccination, and changes in feed or housing. It may be used to help address dietary vitamin and mineral deficiencies in calves and other animals. Intended as a nutritional feed additive for animal use.','route'=>'Oral (in-feed)','prescription'=>'otc','packs'=>'500gm | 1kg | 2.5kg | 5kg | 10kg','desc'=>'To assure adequate intake of vitamins and minerals during critical periods of animals life, vaccination, feed and housing changes, avitaminosis, as immunity system enhancer. Although specially designed for claves but can be given to any animal.'),
  'products/veterinary/solid-dosage-form/ornithon-tablets' => array('name'=>'Ornithon Tablet','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/ornithon-tablet.jpg','active'=>'Chlortetracycline HCl 50 mg','composition'=>'Each tablet contains: Chlortetracycline HCl 50 mg.','drug_class'=>'Tetracycline antibiotic (antibacterial)','uses'=>'A veterinary tetracycline antibiotic used as a feed additive to help control respiratory and enteric bacterial infections in livestock. It is active against a range of susceptible organisms affecting the airways and gastrointestinal tract. To be used under veterinary supervision with appropriate withdrawal periods.','route'=>'Oral (in-feed)','prescription'=>'rx','packs'=>'30\'s | 60\'s | 120\'s','desc'=>'As a feed additive to control respiratory and enteric infections in livestock.'),
  'products/veterinary/solid-dosage-form/oxyline-20-powder' => array('name'=>'Oxyline 20% Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/oxyline-20-powder.jpg','active'=>'Oxytetracycline 20 g per 100 g (20%)','composition'=>'Each 100 g contains: Oxytetracycline 20 g.','drug_class'=>'Tetracycline antibiotic (antibacterial)','uses'=>'A water-soluble veterinary tetracycline antibiotic powder used for the treatment and control of susceptible bacterial infections in poultry. It provides broad-spectrum antibacterial activity against common avian pathogens. To be administered under veterinary supervision with observance of withdrawal periods.','route'=>'Oral (in drinking water)','prescription'=>'rx','packs'=>'100gm | 500gm | 1000gm','desc'=>'For treatment and control of bacterial infections in poultry.'),
  'products/veterinary/solid-dosage-form/polycox-powder' => array('name'=>'Polycox Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/polycox-powder-powder.jpg','active'=>'Sulphamerazine 23 g + Sulphaquinoxaline 10 g + Acetarsol Sodium 14 g + Nitrofurazone 1 g per 100 g','composition'=>'Each 100 g contains: Sulphamerazine 23 g, Sulphaquinoxaline 10 g, Acetarsol Sodium 14 g, Nitrofurazone 1 g.','drug_class'=>'Anticoccidial and antibacterial combination (sulphonamides with an organic arsenical and a nitrofuran)','uses'=>'A veterinary combination powder used in the management of coccidiosis in poultry and certain bacterial conditions of birds, including fowl cholera and salmonellosis (pullorum disease). The sulphonamide and adjunct agents act against susceptible protozoal and bacterial organisms. To be used under veterinary supervision with appropriate withdrawal periods.','route'=>'Oral (in feed or drinking water)','prescription'=>'rx','packs'=>'50gm | 500gm','desc'=>'For the treatment of Coccidiosis in poultry, cholera, salmone and pullurosis in birds.'),
  'products/veterinary/solid-dosage-form/polymycin-plus-powder' => array('name'=>'Polymycin Plus Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/polymycin-plus-powder.jpg','active'=>'Penicillin V Potassium 24 g + Streptomycin Sulphate 72 g + Zinc Bacitracin 104 g per 1000 g','composition'=>'Each 1000 g contains: Penicillin V Potassium 24 g, Streptomycin Sulphate 72 g, Zinc Bacitracin 104 g.','drug_class'=>'Antibacterial combination (beta-lactam penicillin, aminoglycoside and polypeptide antibiotic)','uses'=>'A veterinary antibacterial powder combining penicillin, streptomycin and bacitracin for application to minor wounds such as cuts, scrapes and burns. It is intended to help prevent or address mild superficial skin infections caused by susceptible organisms. To be used under veterinary supervision.','route'=>'Topical (dusting powder)','prescription'=>'rx','packs'=>'100gm | 500gm | 1kg | 2.5kg | 5kg | 25kg','desc'=>'To treat minor wounds (such as cuts, scrapes, burns) and to help prevent or treat mild skin infections.'),
  'products/veterinary/solid-dosage-form/polymycin-powder' => array('name'=>'Polymycin Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/polymycin-powder.jpg','active'=>'Streptomycin Sulphate 25 g + Penicillin V Potassium 5 g per 450 g','composition'=>'Each 450 g contains: Streptomycin Sulphate 25 g, Penicillin V Potassium 5 g (Innovator Specification).','drug_class'=>'Antibacterial combination (aminoglycoside with beta-lactam penicillin)','uses'=>'A veterinary antibacterial dusting powder combining streptomycin and penicillin for application to minor wounds such as cuts, scrapes and burns. It is intended to help prevent or address mild superficial skin infections caused by susceptible bacteria. To be used under veterinary supervision.','route'=>'Topical (dusting powder)','prescription'=>'rx','packs'=>'1oz | 4oz | 1Lb | 100gm | 1kg','desc'=>'To treat minor wounds (such as cuts, scrapes, burns) and to help prevent or treat mild skin infections.'),
  'products/veterinary/solid-dosage-form/prevecox-20-powder' => array('name'=>'Prevecox 20 Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/prevecox-20-powder.jpg','active'=>'Amprolium 200 mg per gram (20%)','composition'=>'Each gram contains: Amprolium 200 mg.','drug_class'=>'Anticoccidial (coccidiostat / antiprotozoal)','uses'=>'A veterinary coccidiostat containing amprolium used for the treatment and prevention of coccidiosis in calves, sheep, goats, chickens (broilers and breeders) and other fowl such as turkeys. It is active against Eimeria species, including Eimeria tenella and Eimeria necatrix. To be administered under veterinary supervision with appropriate withdrawal periods.','route'=>'Oral (in feed or drinking water)','prescription'=>'rx','packs'=>'250gm | 500gm | 1kg','desc'=>'Amprolium is a coccidiostat (antiprotozoal) used for the treatment and prevention of coccidiosis in calves, sheep, goats, chickens (broilers and breeders) and other fowl such as turkeys, with activity against Eimeria spp., especially Eimeria tenella and Eimeria necatrix.'),
  'products/veterinary/solid-dosage-form/str-600-powder' => array('name'=>'STR-600 Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/str-600-powder.jpg','active'=>'Oxytetracycline HCl 250 g, Neomycin Sulphate 100 g, Furaltadone 250 mg, Sodium Ascorbate (Vitamin C) 100 g, Vitamin D3 5,000,000 IU, Vitamin E 1 g, Sulphate 60 g, Vitamin A 2,500,000 IU (per 1000 g)','composition'=>'Each 1000 g contains: Oxytetracycline HCl 250 g, Neomycin Sulphate 100 g, Furaltadone 250 mg, Sodium Vitamin C 100 g, Vitamin D3 5,000,000 IU, Vitamin E 1 g, Sulphate 60 g, Vitamin A 2,500,000 IU.','drug_class'=>'Combination broad-spectrum antibacterial (tetracycline + aminoglycoside + nitrofuran) with supplemental fat-soluble and water-soluble vitamins','uses'=>'A veterinary oral powder combining antibacterial agents with vitamins, used for the prevention and treatment of bacterial infections of various origins, including those associated with Staphylococci, E. coli, Pasteurella and Salmonella. It is intended to support animals during periods of stress such as transport, rehousing, changes of feed and heat stress.','route'=>'Oral (administered in drinking water or feed)','prescription'=>'rx','packs'=>'250gm | 500gm | 1kg | 2.5kg','desc'=>'Prevention and treatment of bacterial infections of different origins (Staphylococci, E. Coli, Pasteurella, Salmonella) to prevent losses often occurring after transport, rehousing, change of feed, heat stress. For good performance and optimal results in animal production.'),
  'products/veterinary/solid-dosage-form/str-acetyl-c-powder' => array('name'=>'STR-Acetyl-C Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/str-acetyl-c-powder.jpg','active'=>'Acetylsalicylic Acid 6.70 g, Vitamin C (Ascorbic Acid) 20 g (per 100 g)','composition'=>'Each 100 g contains: Acetylsalicylic Acid 6.70 g, Vitamin C (Ascorbic Acid) 20 g.','drug_class'=>'Non-steroidal anti-inflammatory (salicylate) analgesic/antipyretic combined with an antioxidant vitamin (Vitamin C)','uses'=>'A veterinary oral powder combining acetylsalicylic acid with vitamin C. Acetylsalicylic acid has analgesic and antipyretic properties, while vitamin C supports cellular oxidation-reduction processes and helps maintain the animal\'s resistance during conditions such as infection, physical fatigue and stress.','route'=>'Oral (administered in drinking water or feed)','prescription'=>'rx','packs'=>'100gm | 500gm | 1kg | 2.5kg','desc'=>'Vitamin C intervenes actively as hydrogen carrier in the cellular oxidation reduction process. It acts powerfully in the stimulation of endocrine secretions particularly in the suprarenal pituitary glands and ovary level. Vitamin C is essential for the resistance to various conditions such as infections toxicity, physical fatigue and over-exertion because of its role in the adoption syndrome. Moreover it has proved useful in allergies in growth symptoms and in the osseous tissue level. Acetyl Salicylic Acid is an analgesic and antipyretic which relieves from pains due to aggressive reactions.'),
  'products/veterinary/solid-dosage-form/sulphadimidine-powder-70' => array('name'=>'Sulphadimidine Powder 70%','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/sulphadimidine-powder-70%.jpg','active'=>'Sulphadimidine Sodium 700 g, Dextrose Anhydrous 300 g (per 1 kg)','composition'=>'Each kg contains: Sulphadimidine Sodium 700 g, Dextrose Anhydrous 300 g.','drug_class'=>'Sulphonamide antibacterial','uses'=>'A veterinary oral sulphonamide powder used against gram-positive and gram-negative bacteria such as Pasteurella, Salmonella and coliform organisms. It is indicated where sulphadimidine therapy is appropriate, including respiratory and gastrointestinal infections, pasteurellosis (haemorrhagic septicaemia), actinobacillosis, actinomycosis, colibacillosis and coccidiosis in animals including poultry.','route'=>'Oral (administered in drinking water or feed)','prescription'=>'rx','packs'=>'250gm | 500gm | 1kg | 2.5kg | 3kg | 5kg','desc'=>'Sulphadimidine is lethal for both gram-positive and gram-negative bacterial. i.e. Pasteurella, Salmonella & Coliform organisms. it is a drug of choice whenever Sulphadimidine therapy is indicated, for example pyogenic respiratory or gastro-intestinal infections. It is ideal for pasteurellosis (Haemorrhagic septicaemia) Actinobacillosis (Wooden tongue) Actinomycosis (Lumpy jaw) collibacillosis and in Coccidiosis of all animals including poultry. In poultry or other animals when given orally Sulphadimidine solution absorbed immediately from the gastro-intestinal tract and it provides an appropriate and therapeutic concentration in the blood.'),
  'products/veterinary/solid-dosage-form/sulphadimidine-sodium-powder-20' => array('name'=>'Sulphadimidine Sodium Powder 20%','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/sulphadimidine-powder-20%.jpg','active'=>'Sulphadimidine Sodium 200 g, Dextrose Anhydrous 800 g (per 1 kg)','composition'=>'Each kg contains: Sulphadimidine Sodium 200 g, Dextrose Anhydrous 800 g.','drug_class'=>'Sulphonamide antibacterial','uses'=>'A veterinary oral sulphonamide powder used for the prevention and treatment of infections caused by micro-organisms susceptible to sulphadimidine. These include respiratory and gastrointestinal infections, actinobacillosis, mastitis, polyarthritis, colibacillosis, salmonellosis, urogenital tract infections, foot rot and coccidiosis in calves and poultry.','route'=>'Oral (administered in drinking water or feed)','prescription'=>'rx','packs'=>'250gm | 500gm | 1kg | 25kg | 3kg | 5kg','desc'=>'For prevention and treatment of infections caused by micro-organism susceptible to Sulphadimidine such as Respiratory and Gastrointestinal infections, Actinobacillosis, Mastitis, Poly-arthritis, Actinomyces spp., Colibacillosis, Salmonellosis, Uro-genital tract infections, Foot Rot and Coccidiosis in Calves and Poultry.'),
  'products/veterinary/solid-dosage-form/sulphadimidine-sodium-powder-50' => array('name'=>'Sulphadimidine Sodium Powder 50%','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/sulphadimidine-powder-50%.jpg','active'=>'Sulphadimidine Sodium 500 g, Dextrose Anhydrous 500 g (per 1 kg)','composition'=>'Each kg contains: Sulphadimidine Sodium 500 g, Dextrose Anhydrous 500 g.','drug_class'=>'Sulphonamide antibacterial','uses'=>'A veterinary oral sulphonamide powder used for the treatment of infections caused by micro-organisms, including both bacteria and coccidia, that are susceptible to sulphadimidine.','route'=>'Oral (administered in drinking water or feed)','prescription'=>'rx','packs'=>'250gm | 500gm | 1kg | 25kg | 3kg | 5kg','desc'=>'For the treatment of infections caused by micro-organisms (both bacteria and coccidia) susceptible to sulphadimidine.'),
  'products/veterinary/solid-dosage-form/tagafon-powder' => array('name'=>'Tagafon Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/tagafon-powder.jpg','active'=>'Trichlorfon 950 mg, Silicon Dioxide 50 mg (per 1 g)','composition'=>'Each g contains: Trichlorfon 950 mg, Silicon Dioxide 50 mg.','drug_class'=>'Organophosphate antiparasitic (ectoparasiticide and endoparasiticide)','uses'=>'A veterinary organophosphate powder effective against a range of internal and external parasites by direct application or oral administration. It is used to help control parasites such as ascarids, bots, pinworms, grubs, lice and ticks in domestic animals. It is not active against flukes or tapeworms.','route'=>'Oral or topical (oral administration or direct application)','prescription'=>'rx','packs'=>'100gm | 500gm | 1000gm | 10gm','desc'=>'It is effective against a wide range of ectoparasites and endoparasites either by direct application or by oral administration. Tagafon powder has an excellent stomach poison action and a good contact & breathing poisons action. Tagafon powder has a broad spectrum of activity being especially effective for the control of parasites such as ascarides, bots, pinworms grubs, soreworms,lice, ticks of domestic animals. It has no action against flukes or tapeworms.'),
  'products/veterinary/solid-dosage-form/taradox-powder' => array('name'=>'Taradox Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/taradox-powder.jpg','active'=>'Doxycycline Hyclate 40 g, Tylosin Tartrate 20 g, Colistin Sulphate 10 g, Bromhexine 2 g (per 100 g)','composition'=>'Each 100 g contains: Doxycycline Hyclate (BP) 40 g, Tylosin Tartrate (BP) 20 g, Colistin Sulphate (BP) 10 g, Bromhexine (BP) 2 g.','drug_class'=>'Combination antibacterial (tetracycline + macrolide + polymyxin) with a mucolytic (bromhexine)','uses'=>'A veterinary oral powder combining antibacterial agents with a mucolytic, used for the treatment and prevention of respiratory and enteric conditions in poultry such as chronic respiratory disease (CRD/CCRD), fowl cholera, fowl typhoid, infectious coryza, bacterial enteritis and early chick mortality. In large animals it is used for infections caused by organisms sensitive to its components.','route'=>'Oral (administered in drinking water or feed)','prescription'=>'rx','packs'=>'100gm | 500gm | 1000gm | 10gm','desc'=>'For the treatment and prevention of C.R.D, C.C.R.D, Fowl Cholera, Fowl Typhoid, Infectious Coryza, Bacterial Enteritis, Early chick mortality and other Respiratory tract infections. In large animals infections caused by Tylosin, Doxycycline, Colistin & Bromhexine sensitive organisms.'),
  'products/veterinary/solid-dosage-form/tetraclozan-sheep-900mg-bolus' => array('name'=>'Tetraclozan Sheep 900 mg Bolus','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/tetraclozan-sheep-900mg-bolus.jpg','active'=>'Tetramisole HCl 450 mg, Oxyclozanide 450 mg (per bolus)','composition'=>'Each bolus contains: Tetramisole HCl 450 mg, Oxyclozanide 450 mg.','drug_class'=>'Combination anthelmintic (imidazothiazole nematocide + salicylanilide flukicide)','uses'=>'A veterinary oral bolus combining an anthelmintic and a flukicide, used for the treatment and control of gastrointestinal and pulmonary nematode infections and chronic fascioliasis caused by adult liver flukes in sheep and goats.','route'=>'Oral (bolus)','prescription'=>'rx','packs'=>'14x4\'s bolus pack.','desc'=>'For the treatment & control of gastrointestinal & pulmonary nematode infection and chronic fascioliasiscaused by adult liver flukesin Sheep & Goats.'),
  'products/veterinary/solid-dosage-form/triconex-powder' => array('name'=>'Triconex Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/triconex-powder.jpg','active'=>'Dimetridazole 750 mg (per 1 g)','composition'=>'Each g contains: Dimetridazole 750 mg.','drug_class'=>'Nitroimidazole antiprotozoal / antimicrobial','uses'=>'A veterinary oral antimicrobial powder used in pigeons for a range of intestinal infections caused by protozoa and bacteria. It is used for the treatment and control of trichomoniasis, amoebiasis and intestinal infections, and also has activity against tapeworms.','route'=>'Oral (administered in drinking water)','prescription'=>'rx','packs'=>'60gm | 100gm | 500gm | 5sachets of 5gm','desc'=>'Triconex Powder is a combination of two antimicrobial agents, effective in wide range of intestinal infections caused by protozoa and bacteria in pigeons. Triconex is a drug of choice for the treatment and control of trichomoniasis, amoebiasis, and intestinal infections. Also it has an activity against tape worms.'),
  'products/veterinary/solid-dosage-form/triconex-powder-14-25mg' => array('name'=>'Triconex Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/triconex-14.25powder.jpg','active'=>'Dimetridazole 50.00 mg, Aminosidine (Paromomycin) Sulphate 14.25 mg (per 1 g)','composition'=>'Each g contains: Dimetridazole 50.00 mg, Aminosidine (Sulphate) 14.25 mg.','drug_class'=>'Combination antimicrobial (nitroimidazole antiprotozoal + aminoglycoside antibacterial)','uses'=>'A veterinary oral powder combining two antimicrobial agents, used in pigeons for a range of intestinal infections caused by protozoa and bacteria. It is used for the treatment and control of trichomoniasis, amoebiasis and intestinal infections, and also has activity against tapeworms.','route'=>'Oral (administered in drinking water)','prescription'=>'rx','packs'=>'60gm | 100gm | 500gm | 5sachets of 5gm','desc'=>'Triconex Powder is a combination of two antimicrobial agents, effective in wide range of intestinal infections caused by protozoa and bacteria in pigeons. Triconex is a drug of choice for the treatment and control of trichomoniasis, amoebiasis, and intestinal infections. Also it has an activity against tape worms.'),
  'products/veterinary/solid-dosage-form/triple-sulpha-powder' => array('name'=>'Triple Sulpha Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/triple-sulpha-powder.jpg','active'=>'Sulphadimidine Sodium 250 g, Sulphadiazine Sodium 250 g, Sulphathiazole Sodium 250 g, Dextrose Anhydrous 250 g (per kg)','composition'=>'Each kg contains: Sulphadimidine Sodium 250 g, Sulphadiazine Sodium 250 g, Sulphathiazole Sodium 250 g, Dextrose Anhydrous 250 g.','drug_class'=>'Sulphonamide antibacterial combination (triple sulpha) with dextrose as energy source','uses'=>'A veterinary oral powder containing a combination of three sulphonamide antibacterials supported with dextrose. It is indicated in the management of enteric (diarrhoeal) conditions, respiratory tract infections and intestinal coccidiosis caused by susceptible organisms in livestock and poultry. Should be used under veterinary supervision.','route'=>'Oral (in drinking water or feed)','prescription'=>'rx','packs'=>'100gm | 250gm | 500gm | 1kg','desc'=>'It\'s used to treat diarrhea, respiratory tract infections, and intestinal coccidiosis.'),
  'products/veterinary/solid-dosage-form/trisolizine-bolus' => array('name'=>'Trisolizine Bolus','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/trisolizine-bolus.jpg','active'=>'Trimethoprim 200 mg, Sulphadiazine 1000 mg','composition'=>'Each bolus contains: Trimethoprim 200 mg, Sulphadiazine 1000 mg.','drug_class'=>'Potentiated sulphonamide antibacterial (trimethoprim + sulphadiazine combination)','uses'=>'A veterinary oral bolus combining trimethoprim with the sulphonamide sulphadiazine, providing broad-spectrum antibacterial coverage. It is used in the management of bacterial infections in calves, cattle, cows, goats, sheep and poultry caused by susceptible organisms. To be administered under veterinary supervision.','route'=>'Oral (bolus)','prescription'=>'rx','packs'=>'10\'s | 30\'s | 50\'s | 100\'s','desc'=>'It is used for the treatment of bacterial infections in Calves, Cattle, Cows, Goats, Poultry and Sheep.'),
  'products/veterinary/solid-dosage-form/tylexin-m-powder' => array('name'=>'Tylexin M Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/tylexin-m-powder.jpg','active'=>'Doxycycline HCl 200 g, Tylosin Tartrate 100 g, Bromhexine 5 g (per 1000 g)','composition'=>'Each 1000 g of powder contains: Doxycycline HCl 200 g, Tylosin Tartrate 100 g, Bromhexine 5 g (as per innovator\'s specification).','drug_class'=>'Antibacterial combination — tetracycline (doxycycline) plus macrolide (tylosin) with a mucolytic (bromhexine)','uses'=>'A veterinary water-soluble powder combining the antibiotics doxycycline and tylosin with the mucolytic bromhexine. It is intended for the management of respiratory tract infections in poultry and ornamental birds caused by susceptible organisms, with bromhexine assisting clearance of respiratory secretions. Use under veterinary supervision.','route'=>'Oral (in drinking water)','prescription'=>'rx','packs'=>'100gm | 500gm | 1000gm','desc'=>'Medicine for respiratory infections in poultry and ornamental birds.'),
  'products/veterinary/solid-dosage-form/tylexin-powder' => array('name'=>'Tylexin Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/tylexin-powder.jpg','active'=>'Doxycycline HCl 200 g, Tylosin Tartrate 100 g, Bromhexine 20 g (per kg)','composition'=>'Each kg contains: Doxycycline HCl 200 g, Tylosin Tartrate 100 g, Bromhexine 20 g (as per innovator\'s specification).','drug_class'=>'Antibacterial combination — tetracycline (doxycycline) plus macrolide (tylosin) with a mucolytic (bromhexine)','uses'=>'A veterinary oral powder combining the antibiotics doxycycline and tylosin with the mucolytic bromhexine. It is used in the management and control of chronic respiratory disease (CRD/CCRD), fowl cholera, infectious coryza, bacterial enteritis and other respiratory tract infections caused by susceptible organisms in poultry and large animals. To be used under veterinary supervision.','route'=>'Oral (in drinking water or feed)','prescription'=>'rx','packs'=>'100gm | 500gm | 1000gm','desc'=>'For the treatment and prevention of CRD, CCRD, Fowl Cholera, Fowl Typhiodlnfectious Coryza, Bacterial Enterities. Early chick mortality and other Respiratory tract infections in large animals infection caused by Tylosin Doxyxcline Colistin 8L Bromhexine sensitive organism.'),
  'products/veterinary/solid-dosage-form/tylovital-f-powder' => array('name'=>'Tylovital-F Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/tylovital-f-powder.jpg','active'=>'Tylosin Tartrate 20 g, Erythromycin Thiocyanate 50 g, Furaltadone 100 g, Vitamin A 2,500,000 IU, Vitamin D3 1,000,000 IU, Vitamin E Acetate 10 g (per kg)','composition'=>'Each kg contains: Tylosin Tartrate 20 g, Erythromycin Thiocyanate 50 g, Furaltadone 100 g, Vitamin A 2,500,000 IU, Vitamin D3 1,000,000 IU, Vitamin E Acetate 10 g.','drug_class'=>'Antibacterial combination — macrolide antibiotics (tylosin, erythromycin) plus nitrofuran (furaltadone), with vitamin supplementation (A, D3, E)','uses'=>'A veterinary oral powder combining the macrolide antibiotics tylosin and erythromycin with the nitrofuran furaltadone, fortified with vitamins A, D3 and E. It is intended for the management of respiratory tract infections and enteric conditions such as salmonellosis and pullorum disease caused by susceptible organisms, while the added vitamins help support nutritional requirements during antibiotic therapy. Use under veterinary supervision.','route'=>'Oral (in drinking water or feed)','prescription'=>'rx','packs'=>'100gm | 1000gm','desc'=>'Tylovital-F Powder is a combination of Antibiotics with vitamins. Tylosine and Erythromycin are broad spectrum antibiotic especially effective against infections of respiratory tract. Furaltadone has excellent bactericidal property, especially in the prevention and treatment of salmonellosis and pullorum diseases. Vitamins allow control of secondary effects resulting for the use of antibiotics and to meet a deficiency of respective vitamins.'),
  'products/veterinary/solid-dosage-form/uronax-powder' => array('name'=>'Uronax Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/uronax-powder.jpg','active'=>'Methenamine 95 g, Vitamin B1 800 mg, Vitamin B2 920 mg, Vitamin K3 200 mg, Dextrose Anhydrous 3.80 g (per 100 g)','composition'=>'Each 100 g contains: Methenamine 95 g, Vitamin B1 (Thiamine) 800 mg, Vitamin B2 (Riboflavin) 920 mg, Vitamin K3 (Menadione) 200 mg, Dextrose Anhydrous 3.80 g.','drug_class'=>'Urinary antiseptic (methenamine) with vitamin supplementation (B1, B2, K3) and dextrose','uses'=>'A veterinary oral powder containing the urinary antiseptic methenamine combined with vitamins B1, B2 and K3 and dextrose. It is intended to support urinary tract health in livestock and poultry, where methenamine acts as a urinary antiseptic and the added vitamins help meet nutritional requirements. Use under veterinary supervision.','route'=>'Oral (in drinking water or feed)','prescription'=>'rx','packs'=>'100gm | 250gm | 500gm | 1kg','desc'=>'Each 100 gm contains:- Methenamine…95gm, Vitamin B1…800mg, Vitamin B2…920mg, Vitamin K3…200mg, Dextrose Anhydrous…3.80gm.'),
  'products/veterinary/solid-dosage-form/urosulpha-bolus' => array('name'=>'Urosulpha Bolus','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/urosulpha-bolus.jpg','active'=>'Sulphanilamide 1.92 g, Sulphathiazole 320 mg, Urea 3.5 g','composition'=>'Each bolus contains: Sulphanilamide 1.92 g, Sulphathiazole 320 mg, Urea 3.5 g.','drug_class'=>'Intrauterine sulphonamide antibacterial combination with urea','uses'=>'A veterinary intrauterine bolus combining the sulphonamide antibacterials sulphanilamide and sulphathiazole with urea. It is used in cattle for the management of retained placental shreds, metritis and post-partum uterine infections caused by susceptible organisms. To be administered by or under the supervision of a veterinarian.','route'=>'Intrauterine (bolus)','prescription'=>'rx','packs'=>'25 Boluses','desc'=>'For use in retained placenta shreds, metritis and post partum infections in cattle.'),
  'products/veterinary/solid-dosage-form/utenol-pessaries' => array('name'=>'Utenol Pessaries','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/utenol-pessaries.jpg','active'=>'Sulphathiazole 1750 mg, Penicillin G 100,000 IU, Streptomycin Sulphate 50 mg, Ethinyloestradiol 0.5 mg','composition'=>'Each pessary contains: Sulphathiazole 1750 mg, Penicillin G 100,000 IU, Streptomycin Sulphate 50 mg, Ethinyloestradiol 0.5 mg.','drug_class'=>'Intrauterine antibacterial combination — sulphonamide plus penicillin and aminoglycoside antibiotics, with an oestrogen (ethinyloestradiol)','uses'=>'A veterinary intrauterine pessary combining the antibacterials sulphathiazole, penicillin G and streptomycin with the oestrogen ethinyloestradiol. It is used in cows, buffaloes and mares for the prevention and management of bacterial infections of the genital tract caused by susceptible organisms. To be administered by or under the supervision of a veterinarian.','route'=>'Intrauterine (pessary)','prescription'=>'rx','packs'=>'10\'s | 20\'s','desc'=>'For the prevention and treatment of general bacterial infections of genital tract in cow buffaloes and mares.'),
  'products/veterinary/solid-dosage-form/vermisole-10-powder' => array('name'=>'Vermisole 10% Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/vermisole-10-powder.jpg','active'=>'Tetramisole HCl 100 mg, Dextrose Anhydrous 900 mg (per gram)','composition'=>'Each gram contains: Tetramisole HCl 100 mg, Dextrose Anhydrous 900 mg.','drug_class'=>'Broad-spectrum anthelmintic (imidazothiazole — tetramisole)','uses'=>'A veterinary oral broad-spectrum anthelmintic powder containing tetramisole. It is used for the treatment and control of gastrointestinal and pulmonary nematode (roundworm) infections — including ascarids, capillaria, caecal worms and lungworms — in livestock and poultry. Use under veterinary supervision.','route'=>'Oral (in drinking water or feed)','prescription'=>'rx','packs'=>'500gm | 1kg | 5kg | 25kg','desc'=>'A broad specttrum anthelmintic for the treatment & control of nematode infections, including tapeworms (syngasmus) common & large round worms (ascaride) pinworms (capillaria) caecal worms (heterakis) & metarakis & metastongylus.'),
  'products/veterinary/solid-dosage-form/vermisole-30-powder' => array('name'=>'Vermisole 30 Powder','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/vermisole-30-powder.jpg','active'=>'Tetramisole HCl 300 mg, Dextrose Anhydrous 700 mg (per gram)','composition'=>'Each gram contains: Tetramisole HCl 300 mg, Dextrose Anhydrous 700 mg.','drug_class'=>'Broad-spectrum anthelmintic (imidazothiazole — tetramisole)','uses'=>'A veterinary oral anthelmintic powder containing tetramisole at a higher strength. It is used for the treatment and control of roundworm (nematode) infections of the gastrointestinal and respiratory tracts in livestock and poultry. Use under veterinary supervision.','route'=>'Oral (in drinking water or feed)','prescription'=>'rx','packs'=>'500gm | 1kg | 5kg | 25kg','desc'=>'Effective against roundworms.'),
  'products/veterinary/solid-dosage-form/vermisole-bolus' => array('name'=>'Vermisole Bolus','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/vermisole-powder.jpg','active'=>'Tetramisole HCl 2 g','composition'=>'Each bolus contains: Tetramisole HCl 2 g.','drug_class'=>'Anthelmintic (imidazothiazole-class broad-spectrum dewormer)','uses'=>'Veterinary anthelmintic bolus used in the management of gastrointestinal nematode (roundworm) infections in animals. It is administered to support deworming programmes where treatment of susceptible parasitic worms is indicated.','route'=>'Oral','prescription'=>'rx','packs'=>'bolus','desc'=>'For the diagnosis or treatment of parasitic nematode worms infection in the intestine.'),
  'products/veterinary/solid-dosage-form/vernil-600-bolus' => array('name'=>'Vernil 600 Bolus','segment'=>'Veterinary','form'=>'Solid Dosage Forms','img'=>'img/product/veterinary/solid-dosage-form/vernil-600-bolus.jpg','active'=>'Levamisole HCl 600 mg','composition'=>'Each bolus contains: Levamisole HCl 600 mg.','drug_class'=>'Anthelmintic (imidazothiazole-class broad-spectrum dewormer)','uses'=>'Veterinary anthelmintic bolus indicated for the prophylaxis and treatment of worm infections in cattle, calves, goats and sheep. It is used against susceptible gastrointestinal worms, lungworms and tapeworm as part of routine deworming.','route'=>'Oral','prescription'=>'rx','packs'=>'5 bolus | 10 bolus | 50 bolus','desc'=>'Propylaxis and treatment of worm infections in calves, cattle, goats, and sheep-like gastrointestinal worms, lungworms, tapeworm.'),
);
